@Composable
fun SuccessContent(
    display: SuccessDisplay.Data,
    onEvent: ((SuccessEvent) -> Unit)? = null,
    isLoading: Boolean = false,
) {
    val coroutineScope = rememberCoroutineScope()
    val didPrintCard = remember { mutableStateOf(false) }
    val typography = VortexTypography()

    display.vortexPrintingCard?.let {
        val card: @Composable () -> Unit =
            remember { @Composable { VortexItemCard(it, isPrinting = true) } }

        coroutineScope.launch {
            if (getPlatform() == TYPE.DESKTOP) {
                delay(100)
                val shot = captureComposable(card)
                delay(100)
                if (!didPrintCard.value) {
                    didPrintCard.value = true
                    onEvent?.invoke(SuccessEvent.PrintCard(shot))
                }
            }
        }
    }

    Surface(modifier = Modifier.fillMaxSize().background(Color.White)) {
        Column(
            modifier = Modifier
                .padding(24.dp)
                .semantics { liveRegion = LiveRegionMode.Assertive },
        ) {
            Text(
                modifier = Modifier
                    .placeholder(isLoading)
                    .semantics { heading() },
                text = display.title, style = typography.headlineLarge
            )
            CardWithAnimatedBorder {
                Text(
                    modifier = Modifier.padding(12.dp).placeholder(isLoading),
                    text = display.description,
                    style = typography.titleLarge
                )
            }
            Text(
                modifier = Modifier.padding(top = 24.dp).placeholder(isLoading),
                text = display.extraInfo,
                style = typography.bodyLarge
            )
            Spacer(modifier = Modifier.weight(1f))
            Row {
                Spacer(modifier = Modifier.weight(1f))
                Button(
                    modifier = Modifier.height(50.dp).width(270.dp).placeholder(isLoading),
                    onClick = { onEvent?.invoke(SuccessEvent.Close) }) {
                    Text(text = display.doneButton)
                }
            }
        }
    }
}

@Composable
fun CardWithAnimatedBorder(
    modifier: Modifier = Modifier,
       borderColors: List<Color> = emptyList(),
    content: @Composable () -> Unit
) {
    val reduceMotion = LocalReduceMotion.current
    val angle = if (reduceMotion) {
        0f
    } else {
        val infiniteTransition = rememberInfiniteTransition()
        val animated by infiniteTransition.animateFloat(
            initialValue = 0f,
            targetValue = 360f,
            animationSpec =
                infiniteRepeatable(
                    animation = tween(1500, easing = LinearEasing),
                    repeatMode = RepeatMode.Restart
                )
        )
        animated
    }

    val brush =
        if (borderColors.isNotEmpty()) Brush.sweepGradient(borderColors)
        else Brush.sweepGradient(listOf(Color.Gray, Color.White))

    Surface(shape = RoundedCornerShape(20.dp)) {
        Surface(
            modifier =
                Modifier.clipToBounds().fillMaxWidth().padding(1.dp).drawWithContent {
                    rotate(angle) {
                        drawCircle(
                            brush = brush,
                            radius = size.width,
                            blendMode = BlendMode.SrcIn,
                        )
                    }
                    drawContent()
                },
            shape = RoundedCornerShape(19.dp)
        ) {
            Box(modifier = Modifier.padding(8.dp)) { content() }
        }
    }
}