package com.coding.va.selfhelp.domain.use_cases

import androidx.compose.ui.graphics.ImageBitmap
import com.coding.va.selfhelp.domain.respository.PrintingRepo
import org.koin.core.component.KoinComponent
import org.koin.core.annotation.Factory

@Factory
class PrintingUseCase(private val printingRepo: PrintingRepo) : KoinComponent {
    suspend fun printText(text: String): Result<Unit> {
        return printingRepo.printText(text)
    }

    suspend fun printImage(imageBitmap: ImageBitmap): Result<Unit> {
        return printingRepo.printImage(imageBitmap)
    }

    suspend fun cutPaper(): Result<Unit> {
        return printingRepo.cutPaper()
    }
}