package com.coding.va.selfhelp.domain.use_cases

import com.coding.va.selfhelp.domain.model.SocialProvider
import com.coding.va.selfhelp.domain.respository.AuthRepository
import io.ktor.http.encodeURLQueryComponent
import org.koin.core.annotation.Factory

@Factory
class LoginWithProviderUseCase(private val repository: AuthRepository) {

    /**
     * Exchanges the OAuth [code] for a JWT by calling the provider's [SocialProvider.url]
     * with CODE and CALLBACK substituted. On success, the JWT is stored via [AuthRepository].
     *
     * @param provider  The social provider returned by the VOID API.
     * @param code      The `code` query parameter received in the OAuth callback.
     * @param callbackUrl  The same callback URL used when launching the auth URI (must match).
     * @return The JWT string on success.
     */
    suspend operator fun invoke(
        provider: SocialProvider,
        code: String,
        callbackUrl: String,
        codeVerifier: String? = null,
    ): Result<String> {
        // callbackUrl is used as a query param value in the provider URL, so it must be encoded.
        var url = provider.url
            .replace("CODE", code)
            .replace("CALLBACK", callbackUrl.encodeURLQueryComponent())
        if (codeVerifier != null) {
            url += "&code_verifier=$codeVerifier"
        }
        return repository.exchangeCode(url).also { result ->
            result.getOrNull()?.let { jwt ->
                repository.storeJwt(jwt)
            }
        }
    }
}
