package com.coding.va.selfhelp.data.respository

import com.coding.va.selfhelp.data.mapper.toDomain
import com.coding.va.selfhelp.data.network.VoidAuthApi
import com.coding.va.selfhelp.domain.constants.Constants.SETTINGS_KEY_JWT
import com.coding.va.selfhelp.domain.model.SocialProvider
import com.coding.va.selfhelp.domain.respository.AuthRepository
import com.russhwolf.settings.Settings

import org.koin.core.annotation.Single

@Single
class AuthRepositoryImp(
    private val api: VoidAuthApi,
) : AuthRepository {

    private val settings = Settings()

    override suspend fun getSocialProviders(): Result<List<SocialProvider>> {
        return Result.runCatching {
            api.getSocialProviders().map { it.toDomain() }
        }
    }

    override suspend fun exchangeCode(url: String): Result<String> {
        return Result.runCatching { api.exchangeCode(url) }
    }

    override suspend fun loginWithGoogle(idToken: String): Result<String> {
        return Result.runCatching { api.loginWithGoogleToken(idToken) }.also { result ->
            result.getOrNull()?.let { jwt -> storeJwt(jwt) }
        }
    }

    override suspend fun loginWithApple(idToken: String): Result<String> {
        return Result.runCatching { api.loginWithAppleToken(idToken) }.also { result ->
            result.getOrNull()?.let { jwt -> storeJwt(jwt) }
        }
    }

    override fun storeJwt(jwt: String) {
        settings.putString(SETTINGS_KEY_JWT, jwt)
    }

    override fun getJwt(): String? {
        val value = settings.getStringOrNull(SETTINGS_KEY_JWT)
        return if (value.isNullOrBlank()) null else value
    }

    override fun clearJwt() {
        settings.remove(SETTINGS_KEY_JWT)
    }
}
