@file:OptIn(kotlin.time.ExperimentalTime::class)

package com.coding.va.selfhelp.data.respository


import com.coding.va.selfhelp.data.mapper.cardCodeToEntryData
import com.coding.va.selfhelp.data.mapper.toSheetsEntry
import com.coding.va.selfhelp.data.models.GoogleSheetsRequest
import com.coding.va.selfhelp.data.network.GoogleSheetsService
import com.coding.va.selfhelp.data.mapper.englishEffect
import com.coding.va.selfhelp.data.mapper.plinToText
import com.coding.va.selfhelp.data.mapper.toResourcesText
import com.coding.va.selfhelp.data.mapper.toVortexCard
import com.coding.va.selfhelp.di.getPlatform
import com.coding.va.selfhelp.domain.model.EntryType
import com.coding.va.selfhelp.domain.model.ImbueForm
import com.coding.va.selfhelp.domain.model.ItemCraftForm
import com.coding.va.selfhelp.domain.model.MundaneForm
import com.coding.va.selfhelp.domain.model.RechargeForm
import com.coding.va.selfhelp.domain.model.SheetEntryData
import com.coding.va.selfhelp.domain.model.SuccessData
import com.coding.va.selfhelp.domain.model.VortexItemCardDisplay
import com.coding.va.selfhelp.domain.respository.SheetsRepository
import kotlin.time.Clock
import kotlinx.serialization.json.Json


import org.koin.core.annotation.Single

@Single
class SheetsRepositoryImp(
    private val service: GoogleSheetsService,
) : SheetsRepository {

    override suspend fun setPrinted(entry: SheetEntryData): Result<Unit> {
        val body = GoogleSheetsRequest(
            values = listOf(
                listOf(
                    "true"
                )
            )
        )

        return service.updatePrinted(body, entry).map { }
    }

    override suspend fun addCraftedItem(form: ItemCraftForm): Result<SheetEntryData> {
        return Result.runCatching {
            val entry = createSheetEntry(EntryType.CRAFT_ITEM).getOrThrow()
            createCraftedItem(form, entry).getOrThrow()
        }
    }

    override suspend fun addImbue(form: ImbueForm): Result<SheetEntryData> {
        return Result.runCatching {
            val entry = if (form.isPerson) {
                createSheetEntry(EntryType.IMBUE_PERSON).getOrThrow()
            } else {
                createSheetEntry(EntryType.IMBUE_ITEM).getOrThrow()
            }
            createImbue(form, entry).getOrThrow()
        }
    }

    override suspend fun addRecharge(form: RechargeForm): Result<SheetEntryData> {
        return Result.runCatching {
            val entry = createSheetEntry(EntryType.RECHARGE_ITEM).getOrThrow()
            createRechargeItem(form, entry).getOrThrow()
        }
    }

    override suspend fun addMundaneItem(form: MundaneForm): Result<SheetEntryData> {
        return Result.runCatching {
            val entry = createSheetEntry(EntryType.MUNDANE_ITEM).getOrThrow()
            createMundaneItem(form, entry).getOrThrow()
        }
    }

    override suspend fun getPrintData(cardCode: String): Result<SuccessData> {
        return Result.runCatching {
            val entryData = cardCode.cardCodeToEntryData()
            val result = service.getSheetEntry(entryData).getOrThrow()
            if (cardCode == result.values[0][1]) {
                SuccessData(
                    Json.decodeFromString<VortexItemCardDisplay>(result.values[0][2]),
                    SheetEntryData(
                        rowNumber = entryData.rowNumber,
                        itemId = result.values[0][5],
                        getCardCode = result.values[0][1],
                        type = entryData.type,
                        alreadyPrinted = result.values[0][4].toBoolean(),
                    )
                )
            } else {
                throw Exception("Card code mismatch $cardCode - ${result.values[0][1]}")
            }
        }
    }

    private suspend fun createSheetEntry(type: EntryType): Result<SheetEntryData> {
        return service.createSheetEntry(type).map { it.toSheetsEntry(type) }
    }

    private suspend fun createCraftedItem(
        form: ItemCraftForm,
        entry: SheetEntryData
    ): Result<SheetEntryData> {
        val body = GoogleSheetsRequest(
            values = listOf(
                listOf(
                    Clock.System.now().toString(), // A: created
                    entry.getCardCode,             // B: printingId
                    Json.encodeToString(form.toVortexCard(entry.itemId)), // C: vortexcard
                    getPlatform().displayName,     // D: platform
                    "false",                       // E: cardPrinted
                    entry.itemId,                  // F: Item Id
                    form.name,                     // G: ItemName
                    form.description,              // H: ItemDescription
                    "",                            // I: imbue (not applicable for craft)
                    form.imbueCap,                 // J: ImbueCap
                    form.toResourcesText(),         // K: Resources
                    form.notes,                     // L: Notes
                )
            )
        )

        return service.updateSheetEntry(body, entry).map {
            entry
        }
    }

    private suspend fun createImbue(
        form: ImbueForm,
        entry: SheetEntryData
    ): Result<SheetEntryData> {
        val vortexCard = form.toVortexCard(entry.itemId)
        val body = GoogleSheetsRequest(
            values = listOf(
                listOf(
                    Clock.System.now().toString(), // A: created
                    entry.getCardCode,             // B: printingId
                    Json.encodeToString(vortexCard), // C: vortexcard
                    getPlatform().displayName,     // D: platform
                    "false",                       // E: cardPrinted
                    entry.itemId,                  // F: Item Id
                    (form.targetItin ?: form.targetPlin?.plinToText().orEmpty()), // G: ItemName
                    "",                            // H: ItemDescription (not applicable for imbue)
                    vortexCard.power.orEmpty(),    // I: imbue
                    "",                            // J: ImbueCap (not applicable for imbue)
                    form.toResourcesText(),        // K: Resources
                    form.notes,                    // L: Notes
                )
            )
        )
        return service.updateSheetEntry(body, entry).map {
            entry
        }
    }

    private suspend fun createMundaneItem(
        form: MundaneForm,
        entry: SheetEntryData
    ): Result<SheetEntryData> {
        val targetPlinText = when {
            form.selectedSkill?.requiresSecondPlin == true ->
                "${form.targetPlin.plinToText()} + ${form.targetPlin2.plinToText()}"
            form.selectedSkill?.requiresTargetPlin == true ->
                form.targetPlin.plinToText()
            else -> ""
        }
        val body = GoogleSheetsRequest(
            values = listOf(
                listOf(
                    Clock.System.now().toString(), // A: created
                    entry.getCardCode,             // B: printingId
                    Json.encodeToString(form.toVortexCard()), // C: vortexcard
                    getPlatform().displayName,     // D: platform
                    "false",                       // E: cardPrinted
                    entry.itemId,                  // F: Item Id
                    targetPlinText,                // G: target plin(s)
                    form.selectedSkill?.englishEffect().orEmpty(), // H: skill effect
                    "",                            // I: empty
                    "",                            // J: empty
                    form.toResourcesText(),        // K: skill name + quantity + crafter + inspiration
                    form.notes,                    // L: Notes
                )
            )
        )
        return service.updateSheetEntry(body, entry).map { entry }
    }

    private suspend fun createRechargeItem(
        form: RechargeForm,
        entry: SheetEntryData
    ): Result<SheetEntryData> {
        val body = GoogleSheetsRequest(
            values = listOf(
                listOf(
                    Clock.System.now().toString(), // A: created
                    entry.getCardCode,             // B: printingId
                    Json.encodeToString(form.toVortexCard(entry.itemId)), // C: vortexcard
                    getPlatform().displayName,     // D: platform
                    "false",                       // E: cardPrinted
                    entry.itemId,                  // F: Item Id
                    form.targetItin,               // G: ItemName
                    "",                            // H: ItemDescription (not applicable for recharge)
                    "",                            // I: imbue (not applicable for recharge)
                    "",                            // J: ImbueCap (not applicable for recharge)
                    form.toResourcesText(),        // K: Resources
                    form.notes,                    // L: Notes
                )
            )
        )
        return service.updateSheetEntry(body, entry).map {
            entry
        }
    }
}