package com.coding.va.selfhelp.presentation.screens.imbue.navigation

import androidx.navigation.NavGraphBuilder
import androidx.navigation.compose.composable
import androidx.navigation.toRoute
import com.coding.va.selfhelp.presentation.methods.GenericNavType
import com.coding.va.selfhelp.presentation.screens.imbue.ImbueScreen
import com.coding.va.selfhelp.presentation.screens.mainscreen.actions.MainActions
import com.coding.va.selfhelp.presentation.screens.mainscreen.destinations.MainDestinations
import org.koin.compose.koinInject
import kotlin.reflect.typeOf

fun NavGraphBuilder.ImbueRoute(action: MainActions) {
    composable<MainDestinations.Imbue>(
        typeMap = mapOf(
            typeOf<MainDestinations.Imbue>() to GenericNavType(MainDestinations.Imbue.serializer())
        )
    ) {
        val dest = it.toRoute<MainDestinations.Imbue>()
        ImbueScreen(koinInject(), action, dest)
    }
}
