@OptIn(ExperimentalLayoutApi::class)
@Composable
fun RechargeContent(
    display: RechargeDisplay,
    onEvent: ((RechargeEvent) -> Unit)? = null
) {
    val numberRegex = remember { Regex("^\\d+\$") }
    val typography = VortexTypography()
    val strings = LocalStrings.current
    val numericKeyboard = KeyboardOptions(keyboardType = KeyboardType.Number)

    Surface(modifier = Modifier.fillMaxSize().background(Color.White)) {
        display.errorBox?.let {
            ErrorBox(
                display = it,
                onConfirmation = { },
                onDismissRequest = { onEvent?.invoke(RechargeEvent.DismissError) })
        }

        display.verifySheet?.let {
            VerifySheet(
                display = it,
                onConfirm = { onEvent?.invoke(RechargeEvent.AddRecharge) },
                onDismiss = { onEvent?.invoke(RechargeEvent.DismissError) }
            )
        }

        Box(modifier = Modifier.fillMaxSize()) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .verticalScroll(rememberScrollState())
                    .padding(start = 24.dp, top = 24.dp, end = 24.dp, bottom = 80.dp)
            ) {
            Text(
                text = display.title,
                style = typography.headlineLarge,
                modifier = Modifier.semantics { heading() },
            )
            Text(text = display.description, style = typography.titleLarge)

            Column(modifier = Modifier.padding(top = 24.dp)) {
                OutlinedTextField(
                    modifier = Modifier.moveFocusOnTab(),
                    isError = display.shouldValidate && !display.form.isTargetValid(),
                    errorText = if (display.shouldValidate && !display.form.isTargetValid()) strings.a11y.errorRequired else null,
                    value = display.form.targetItin.orEmpty(),
                    placeholder = { Text(text = display.rechargeTarget.hint) },
                    onValueChange = {
                        onEvent?.invoke(
                            RechargeEvent.UpdateRechargeForm(
                                display.form.copy(
                                    targetItin = it
                                )
                            )
                        )
                    },
                    label = { Text(text = display.rechargeTarget.label) }
                )


                OutlinedTextField(
                    modifier = Modifier.height(100.dp).width(350.dp).moveFocusOnTab(),
                    value = display.form.notes,
                    placeholder = { Text(text = display.rechargeNotes.hint) },
                    onValueChange = {
                        onEvent?.invoke(
                            RechargeEvent.UpdateRechargeForm(
                                display.form.copy(
                                    notes = it
                                )
                            )
                        )
                    },
                    label = { Text(text = display.rechargeNotes.label) }
                )
                Text(
                    modifier = Modifier.padding(top = 16.dp, bottom = 16.dp),
                    text = display.rechargeDescription,
                    style = typography.bodyMedium
                )
                display.form.rechargeResources.forEach { entry ->
                    Column {
                        FlowRow(verticalArrangement = Arrangement.Bottom) {
                            OutlinedTextField(
                                modifier = Modifier.width(150.dp).padding(end = 8.dp).moveFocusOnTab(),
                                value = entry.value.energyAmount,
                                isError = display.shouldValidate && !entry.value.isEnergyAmountValid(),
                                errorText = if (display.shouldValidate && !entry.value.isEnergyAmountValid()) strings.a11y.errorNumbersOnly else null,
                                keyboardOptions = numericKeyboard,
                                placeholder = { Text(text = display.rechargeResource.energyAmount.hint) },
                                onValueChange = {
                                    onEvent?.invoke(
                                        RechargeEvent.UpdateRechargeForm(
                                            display.form.copy(
                                                rechargeResources = display.form.rechargeResources.toMutableMap()
                                                    .apply {
                                                        this[entry.key] = entry.value.copy(
                                                            energyAmount = it
                                                        )
                                                    }
                                            )
                                        )
                                    )
                                },
                                label = { Text(text = display.rechargeResource.energyAmount.label) }
                            )

                            SelectableField(
                                modifier = Modifier.width(200.dp).padding(end = 8.dp)
                                    .moveFocusOnTab(),
                                display = display.rechargeResource.energyType,
                                value = entry.value.energyType.localizedName(LocalStrings.current),
                                onSelected = {
                                    onEvent?.invoke(
                                        RechargeEvent.UpdateRechargeForm(
                                            display.form.copy(
                                                rechargeResources = display.form.rechargeResources.toMutableMap()
                                                    .apply {
                                                        this[entry.key] = entry.value.copy(
                                                            energyType = EnergyType.valueOf(it.id)
                                                        )
                                                    }
                                            )
                                        )
                                    )
                                }
                            )

                            PlinTextField(
                                display = display.rechargeResource.plin,
                                modifier = Modifier.padding(end = 8.dp)
                                    .moveFocusOnTab(),
                                isError = display.shouldValidate && !entry.value.isPlinValid(),
                                errorText = if (display.shouldValidate && !entry.value.isPlinValid()) strings.a11y.errorInvalidPlin else null,
                                value = entry.value.headRechargerPlin,
                                onValueChange = {
                                    onEvent?.invoke(
                                        RechargeEvent.UpdateRechargeForm(
                                            display.form.copy(
                                                rechargeResources = display.form.rechargeResources.toMutableMap()
                                                    .apply {
                                                        this[entry.key] = entry.value.copy(
                                                            headRechargerPlin = it,
                                                            energySuppliers = entry.value.energySuppliers.toMutableMap()
                                                                .apply {
                                                                    this[1] = this[1]?.copy(plin = it) ?: RechargeEnergySupplier()
                                                                }
                                                        )
                                                    }
                                            )
                                        )
                                    )
                                },
                            )
                        }
                        Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
                            Text(
                                modifier = Modifier.padding(top = 16.dp),
                                text = display.rechargeResource.energySupplierDescription
                                    .replace(ENERGY_TYPE, entry.value.energyType.localizedName(LocalStrings.current)),
                                style = typography.bodyMedium
                            )
                            Text(
                                modifier = Modifier.padding(bottom = 16.dp),
                                text = display.rechargeResource.currentEnergyLabel + entry.value.energySuppliers.values.mapNotNull { it.amount.toIntOrNull() }.sum(),
                                style = typography.bodyMedium
                            )
                            entry.value.energySuppliers.forEach { supplier ->
                                Row(verticalAlignment = Alignment.Bottom) {
                                    FlowRow(
                                        modifier = Modifier.border(3.dp, secondaryTextColor, RoundedCornerShape(8.dp))
                                            .padding(top = 16.dp, start = 16.dp, end = 16.dp, bottom = 20.dp),
                                    ) {
                                        OutlinedTextField(
                                            modifier = Modifier.width(150.dp).padding(start = 8.dp)
                                                .moveFocusOnTab(),
                                            isError = display.shouldValidate && !entry.value.isEnergyAmountValid(),
                                            errorText = if (display.shouldValidate && !entry.value.isEnergyAmountValid()) strings.a11y.errorNumbersOnly else null,
                                            keyboardOptions = numericKeyboard,
                                            value = supplier.value.amount,
                                            enabled = display.rechargeResource.energySupplierAmount.enabled,
                                            placeholder = { Text(text = display.rechargeResource.energySupplierAmount.hint) },
                                            onValueChange = {
                                                onEvent?.invoke(
                                                    RechargeEvent.UpdateRechargeForm(
                                                        display.form.copy(
                                                            rechargeResources = display.form.rechargeResources.toMutableMap()
                                                                .apply {
                                                                    this[entry.key] = entry.value.copy(
                                                                        energySuppliers = entry.value.energySuppliers.toMutableMap()
                                                                            .apply {
                                                                                this[supplier.key] =
                                                                                    supplier.value.copy(
                                                                                        amount = it
                                                                                    )
                                                                            }
                                                                    )
                                                                }
                                                        )
                                                    )
                                                )
                                            },
                                            label = { Text(text = display.rechargeResource.energySupplierAmount.label) }
                                        )

                                        PlinTextField(
                                            display = display.rechargeResource.energySupplierPlin,
                                            modifier = Modifier.padding(start = 8.dp)
                                                .moveFocusOnTab(),
                                            value = supplier.value.plin,
                                            onValueChange = {
                                                onEvent?.invoke(
                                                    RechargeEvent.UpdateRechargeForm(
                                                        display.form.copy(
                                                            rechargeResources = display.form.rechargeResources.toMutableMap()
                                                                .apply {
                                                                    this[entry.key] = entry.value.copy(
                                                                        energySuppliers = entry.value.energySuppliers.toMutableMap()
                                                                            .apply {
                                                                                this[supplier.key] =
                                                                                    supplier.value.copy(
                                                                                        plin = it
                                                                                    )
                                                                            }
                                                                    )
                                                                }
                                                        )
                                                    )
                                                )
                                            },
                                        )
                                    }
                                    if (entry.value.energySuppliers.size == supplier.key) {
                                        FlowRow {
                                            if (supplier.key > 1) {
                                                Button(
                                                    modifier = Modifier
                                                        .padding(top = 10.dp, start = 12.dp)
                                                        .height(50.dp)
                                                        .width(50.dp)
                                                        .semantics { contentDescription = strings.a11y.removeRow },
                                                    onClick = {
                                                        onEvent?.invoke(
                                                            RechargeEvent.RemovePowerSupplier(entry.key, supplier.key)
                                                        )
                                                    }) {
                                                    Text(text = "-")
                                                }
                                            }
                                            Button(
                                                modifier = Modifier
                                                    .padding(top = 10.dp, start = 12.dp)
                                                    .height(50.dp)
                                                    .width(50.dp)
                                                    .semantics { contentDescription = strings.a11y.addRow },
                                                onClick = {
                                                    onEvent?.invoke(
                                                        RechargeEvent.AddPowerSupplier(entry.key)
                                                    )
                                                }) {
                                                Text(text = "+")
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }

            } // end scrollable Column
            Row(
                modifier = Modifier
                    .align(Alignment.BottomCenter)
                    .fillMaxWidth()
                    .padding(start = 24.dp, end = 24.dp, top = 8.dp, bottom = 16.dp)
            ) {
                Button(
                    modifier = Modifier.height(50.dp).onlyDesktop { width(200.dp) },
                    onClick = { onEvent?.invoke(RechargeEvent.Back) }) {
                    Text(text = display.backButton)
                }
                Spacer(modifier = Modifier.weight(1f))
                Button(
                    modifier = Modifier.height(50.dp).onlyDesktop { width(200.dp) },
                    onClick = { onEvent?.invoke(RechargeEvent.Verify) }) {
                    Text(text = display.nextButton)
                }
            }
        } // end Box
    }
}


