package com.coding.va.selfhelp.presentation.components

import androidx.compose.foundation.layout.RowScope
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.material.minimumInteractiveComponentSize
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp
import com.coding.va.selfhelp.theme.ButtonStyle

/**
 * Wrapper around Material's [androidx.compose.material.Button] with the Vortex
 * brand colors and rounded corners. Enforces a 48dp minimum touch target so
 * icon-only +/- buttons stay WCAG 2.5.5 compliant without per-call tweaks.
 *
 * When [content] is a bare symbol like `Text("+")` callers MUST supply an
 * accessible label via `Modifier.semantics { contentDescription = ... }` —
 * the text glyph alone is not meaningful to assistive technology.
 */
@Composable
fun Button(
    onClick: () -> Unit,
    modifier: Modifier = Modifier,
    enabled: Boolean = true,
    content: @Composable RowScope.() -> Unit
) {
    androidx.compose.material.Button(
        modifier = modifier.minimumInteractiveComponentSize(),
        enabled = enabled,
        colors = ButtonStyle(),
        onClick = onClick,
        shape = RoundedCornerShape(4.dp)
    ) {
        content()
    }
}
