// ---------------------------------------------------------------------------
// Supplier model
// ---------------------------------------------------------------------------

typealias MundaneInspirationSupplier = com.coding.va.selfhelp.domain.model.MundaneInspirationSupplier
typealias MundaneForm = com.coding.va.selfhelp.domain.model.MundaneForm

// ---------------------------------------------------------------------------
// Display
// ---------------------------------------------------------------------------

data class MundaneDisplay(
    val title: String,
    val description: String,
    val skillField: SelectableFieldDisplay,
    val skillRequiredLabel: String,
    val skillResourcesLabel: String,
    val skillEffectLabel: String,
    val crafterPlinField: PlinFieldDisplay,
    val quantityField: FieldDisplay,
    val inspirationSectionTitle: String,
    val inspirationCountLabel: String,
    val inspirationSupplierPlinField: PlinFieldDisplay,
    val inspirationSupplierAmountField: FieldDisplay,
    val inspirationSupplierDescription: String,
    val targetPlinField: PlinFieldDisplay,
    val targetPlin2Field: PlinFieldDisplay,
    val notesField: FieldDisplay,
    val backButton: String,
    val nextButton: String,
    val form: MundaneForm,
    val shouldValidate: Boolean,
    val errorBox: ErrorBoxDisplay?,
    val verifySheet: VerifySheetDisplay?,
)

// ---------------------------------------------------------------------------
// Validation helpers
// ---------------------------------------------------------------------------

fun MundaneForm.isSkillSelected(): Boolean = selectedSkill != null

fun MundaneForm.isCrafterPlinValid(): Boolean =
    crafterPlin.first.isNotBlank() && crafterPlin.second.isNotBlank()

fun MundaneForm.isTargetPlinValid(): Boolean =
    if (selectedSkill?.requiresTargetPlin == true)
        targetPlin.first.isNotBlank() && targetPlin.second.isNotBlank()
    else true

fun MundaneForm.isTargetPlin2Valid(): Boolean =
    if (selectedSkill?.requiresSecondPlin == true)
        targetPlin2.first.isNotBlank() && targetPlin2.second.isNotBlank()
    else true

fun MundaneForm.isQuantityValid(): Boolean =
    if (selectedSkill?.hasQuantity == true)
        quantity.isNotBlank() && (quantity.toIntOrNull() ?: 0) > 0
    else true

/** True if the user has started filling this row (either plin or amount has a value). */
fun MundaneInspirationSupplier.isFilled(): Boolean =
    plin.first.isNotBlank() || amount.isNotBlank()

/** Valid when either completely empty OR fully filled (plin + chin + amount). */
fun MundaneInspirationSupplier.isValid(): Boolean =
    !isFilled() || (plin.first.isNotBlank() && plin.second.isNotBlank() && amount.isNotBlank())

fun MundaneForm.isInspirationSuppliersValid(): Boolean =
    inspirationSuppliers.values.all { it.isValid() }

/** True when at least one supplier row has been started. */
fun MundaneForm.hasAnyInspirationSupplied(): Boolean =
    inspirationSuppliers.values.any { it.isFilled() }

/** Sum of all entered inspiration amounts across every supplier row. */
fun MundaneForm.totalInspirationSupplied(): Int =
    inspirationSuppliers.values.sumOf { it.amount.toIntOrNull() ?: 0 }

/** Total inspiration required for the selected skill, taking quantity into account. */
fun MundaneForm.requiredInspirationTotal(): Int {
    val base = selectedSkill?.requiredInspiration ?: 0
return     if (selectedSkill?.hasQuantity == true) base * (quantity.toIntOrNull() ?: 1)
    else base
}

/**
 * If any suppliers are filled in, the total supplied must match what the skill requires.
 * Empty section (materials used) is always valid.
 */
fun MundaneForm.isInspirationTotalValid(): Boolean =
    !hasAnyInspirationSupplied() || totalInspirationSupplied() == requiredInspirationTotal()

fun MundaneForm.isValid(): Boolean =
    isSkillSelected() &&
        isCrafterPlinValid() &&
        isTargetPlinValid() &&
        isTargetPlin2Valid() &&
        isQuantityValid() &&
        isInspirationSuppliersValid() &&
        isInspirationTotalValid()

fun MundaneForm.meetsMinRequirements(): Boolean =
    isSkillSelected() && isCrafterPlinValid()

// ---------------------------------------------------------------------------
// Mappers
// ---------------------------------------------------------------------------

fun MundaneForm.toResourcesText(): String {
    val qtyPart = if (selectedSkill?.hasQuantity == true) " x$quantity" else ""
    val baseText = EnStrings.mundane.mundaneResourceEntry
        .replace(SKILL, selectedSkill?.localizedName(EnStrings).orEmpty())
        .replace(QTY, qtyPart)
        .replace(PLIN, crafterPlin.plinToText())
    val suppliers = inspirationSuppliers.values.filter { it.plin.first.isNotBlank() }
    return if (suppliers.isNotEmpty()) {
        baseText + "\n${EnStrings.mundane.inspirationSuppliedByLabel}" +
            suppliers.joinToString("\n") {
                EnStrings.mundane.inspirationEntry
                    .replace(AMOUNT, it.amount)
                    .replace(PLIN, it.plin.plinToText())
            }
    } else {
        "$baseText${EnStrings.mundane.materialsUsed}"
    }
}

fun MundaneForm.toVortexCard(itemId: String? = null): VortexItemCardDisplay {
    val targetText = when {
        selectedSkill?.requiresSecondPlin == true ->
            "${targetPlin.plinToText()} + ${targetPlin2.plinToText()}"
        selectedSkill?.requiresTargetPlin == true ->
            targetPlin.plinToText()
        else -> null
    }
    return VortexItemCardDisplay(
        header = EnStrings.mundane.vortexCardHeader,
        tempItin = itemId,
        itemName = selectedSkill?.localizedName(EnStrings),
        itemDescription = null,                 // no description on front
        createdBy = crafterPlin.plinToText(),
        targetPlin = targetText,                // target plin(s) on front
        power = selectedSkill?.localizedEffect(EnStrings), // effect text on back — always English
        event = currentEventName(),
    )
}

fun MundaneForm.toVerifySheet(hasErrors: Boolean, isEnabled: Boolean, strings: AppStrings): VerifySheetDisplay =
    VerifySheetDisplay(
        title = if (hasErrors) strings.verify.titleHasErrors else strings.verify.titleNoErrors,
        description = if (hasErrors) strings.verify.descriptionHasErrorsMundane else strings.verify.descriptionNoErrorsMundane,
        dismiss = strings.verify.dismiss,
        confirm = LoadingButtonDisplay(strings.verify.confirm, false, isEnabled),
        resources = toResourcesText(),
        notes = notes,
        lammyLabel = strings.verify.mundaneLammyLabel,
        lammy = toVortexCard(),
    )
