package com.coding.va.selfhelp.presentation.screens.character.detail

import com.coding.va.selfhelp.domain.model.CharacterDetail
import com.coding.va.selfhelp.i18n.AppStrings
import com.coding.va.selfhelp.presentation.screens.character.detail.model.CharacterConditionDisplay
import com.coding.va.selfhelp.presentation.screens.character.detail.model.CharacterDetailScreenDisplay
import com.coding.va.selfhelp.presentation.screens.character.detail.model.CharacterImbueDisplay
import com.coding.va.selfhelp.presentation.screens.character.detail.model.CharacterItemDisplay
import com.coding.va.selfhelp.presentation.screens.character.detail.model.CharacterPowerDisplay
import com.coding.va.selfhelp.presentation.screens.character.detail.model.CharacterSkillDisplay

object CharacterDetailDisplayProvider {

    fun loading(): CharacterDetailScreenDisplay = CharacterDetailScreenDisplay.Loading

    fun display(strings: AppStrings, detail: CharacterDetail): CharacterDetailScreenDisplay.Display {
        val s = strings.character
        return CharacterDetailScreenDisplay.Display(
            name = detail.name,
            xp = detail.xp,
            belief = detail.belief,
            group = detail.group,
            world = detail.world,
            faction = detail.faction,
            status = detail.status,
            xpLabel = s.xpLabel,
            beliefLabel = s.beliefLabel,
            groupLabel = s.groupLabel,
            worldLabel = s.worldLabel,
            factionLabel = s.factionLabel,
            statusLabel = s.statusLabel,
            tabSkills = s.tabSkills,
            tabConditions = s.tabConditions,
            tabItems = s.tabItems,
            tabPowers = s.tabPowers,
            powersHeader = s.powersHeader,
            runeImbuesHeader = s.runeImbuesHeader,
            glyphImbuesHeader = s.glyphImbuesHeader,
            skills = detail.skills.map { skill ->
                CharacterSkillDisplay(
                    id = skill.id,
                    name = skill.name,
                    times = skill.times,
                    cost = skill.cost,
                    manaAmount = skill.manaAmount,
                    manatypeName = skill.manatypeName,
                    loresheet = skill.loresheet,
                    costLabel = s.skillCostLabel,
                    timesLabel = s.skillTimesLabel,
                    manaLabel = s.skillManaLabel,
                    loresheetLabel = s.skillLoresheetLabel,
                    loresheetUrl = if (skill.loresheet) getLoresheetUrl(skill.name) else null,
                )
            },
            conditions = detail.conditions.map { condition ->
                CharacterConditionDisplay(
                    coin = condition.coin,
                    name = condition.name,
                    expiry = condition.expiry,
                    expiryLabel = s.expiryLabel,
                    noExpiry = s.noExpiry,
                )
            },
            items = detail.items.map { item ->
                CharacterItemDisplay(
                    name = item.name,
                    itin = item.itin,
                    expiry = item.expiry,
                    expiryLabel = s.expiryLabel,
                    noExpiry = s.noExpiry,
                )
            },
            powers = detail.powers.map { power ->
                CharacterPowerDisplay(
                    poin = power.poin,
                    name = power.name,
                    expiry = power.expiry,
                    expiryLabel = s.expiryLabel,
                    noExpiry = s.noExpiry,
                )
            },
            runeImbues = detail.runeImbues.map { rune ->
                CharacterImbueDisplay(
                    name = rune.name,
                    expiry = rune.expiry,
                    expiryLabel = s.expiryLabel,
                    noExpiry = s.noExpiry,
                )
            },
            glyphImbues = detail.glyphImbues.map { glyph ->
                CharacterImbueDisplay(
                    name = glyph.name,
                    expiry = glyph.expiry,
                    expiryLabel = s.expiryLabel,
                    noExpiry = s.noExpiry,
                )
            },
            emptySkills = s.emptySkills,
            emptyConditions = s.emptyConditions,
            emptyItems = s.emptyItems,
            emptyPowers = s.emptyPowers,
            energyTotals = null, // populated separately via parallel fetch
            energyLabel = s.energyLabel,
            backButton = s.backButton,
            switchCharacterButton = s.switchCharacterButton,
            logoutButton = s.logoutButton,
            logoutConfirmMessage = s.logoutConfirmMessage,
            logoutConfirmButton = s.logoutConfirmButton,
            logoutCancelButton = s.logoutCancelButton,
        )
    }

    fun error(strings: AppStrings): CharacterDetailScreenDisplay =
        CharacterDetailScreenDisplay.Error(
            message = strings.character.errorMessage,
            retryButton = strings.character.retryButton,
            backButton = strings.character.backButton,
        )
}
