package com.coding.va.selfhelp.data.respository

import com.coding.va.selfhelp.BuildKonfig
import com.coding.va.selfhelp.di.getPlatform
import com.coding.va.selfhelp.domain.respository.RemoteConfigRepository
import com.coding.va.selfhelp.utils.TYPE

import dev.gitlive.firebase.Firebase
import dev.gitlive.firebase.remoteconfig.get
import dev.gitlive.firebase.remoteconfig.remoteConfig
import io.ktor.client.HttpClient
import io.ktor.client.request.header
import io.ktor.client.request.post
import io.ktor.client.request.setBody
import io.ktor.client.statement.bodyAsText
import io.ktor.http.ContentType
import io.ktor.http.contentType
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import kotlin.time.Clock
import kotlin.time.ExperimentalTime
import com.coding.va.selfhelp.data.di.SHEETS_CLIENT
import org.koin.core.annotation.Named
import org.koin.core.annotation.Single

private const val TAG = "[RemoteConfig]"

@Single
class RemoteConfigDataRepository(
    @Named(SHEETS_CLIENT) private val httpClient: HttpClient
) : RemoteConfigRepository {

    init {
        println("$TAG Repository initialized on platform=${getPlatform()}")
    }

    @OptIn(ExperimentalTime::class)
    override suspend fun canMakeCreation(): Result<Boolean> {
        return if (getPlatform() == TYPE.DESKTOP || BuildKonfig.isDebug) {
            println("$TAG canMakeCreation → bypassed (platform=${getPlatform()}, isDebug=${BuildKonfig.isDebug}), returning true")
            Result.success(true)
        } else {
            println("$TAG canMakeCreation → fetching from Firebase Remote Config...")
            Result.runCatching {
                Firebase.remoteConfig.fetchAndActivate()
                val startTime: Long = Firebase.remoteConfig.get("enableStartTime")
                val endTime: Long = Firebase.remoteConfig.get("enableEndTime")
                val now = Clock.System.now().epochSeconds
                val allowed = now in startTime..endTime
                println("$TAG canMakeCreation → startTime=$startTime endTime=$endTime now=$now → allowed=$allowed")
                allowed
            }.also { result ->
                result.exceptionOrNull()?.let { println("$TAG canMakeCreation → ERROR: ${it.message}") }
            }
        }
    }

    override suspend fun getRemoteSheetsId(): Result<String> {
        return if (getPlatform() == TYPE.DESKTOP) {
            fetchSheetIdViaRest()
        } else {
            fetchSheetIdViaFirebaseSdk()
        }
    }

    private suspend fun fetchSheetIdViaFirebaseSdk(): Result<String> {
        println("$TAG getRemoteSheetsId → calling fetchAndActivate then reading 'googleSheetId'...")
        return Result.runCatching {
            val activated = Firebase.remoteConfig.fetchAndActivate()
            println("$TAG getRemoteSheetsId → fetchAndActivate completed, activated=$activated")
            val sheetId = Firebase.remoteConfig.get<String>("googleSheetId")
            if (sheetId.isBlank()) error("googleSheetId is empty after fetch — check Firebase Remote Config console")
            sheetId
        }.also { result ->
            result.onSuccess { println("$TAG getRemoteSheetsId → SUCCESS sheetId='$it'") }
            result.onFailure { println("$TAG getRemoteSheetsId → ERROR: ${it.message}") }
        }
    }

    private suspend fun fetchSheetIdViaRest(): Result<String> {
        println("$TAG getRemoteSheetsId → desktop: fetching via REST API...")
        return Result.runCatching {
            val projectNumber = BuildKonfig.FIREBASE_APPLICATION_ID.split(":")[1]
            val url = "https://firebaseremoteconfig.googleapis.com/v1/projects/$projectNumber/namespaces/firebase:fetch"
            val response = httpClient.post(url) {
                contentType(ContentType.Application.Json)
                header("x-goog-api-key", BuildKonfig.FIREBASE_API_KEY)
                setBody("""{"appId":"${BuildKonfig.FIREBASE_APPLICATION_ID}","appInstanceId":"desktop"}""")
            }
            val json = Json.parseToJsonElement(response.bodyAsText()).jsonObject
            val entries = json["entries"]?.jsonObject
                ?: error("No 'entries' in Remote Config response")
            val sheetId = entries["googleSheetId"]?.jsonPrimitive?.content
                ?: error("'googleSheetId' not found in Remote Config entries")
            if (sheetId.isBlank()) error("googleSheetId is empty — check Firebase Remote Config console")
            sheetId
        }.also { result ->
            result.onSuccess { println("$TAG getRemoteSheetsId → SUCCESS (REST) sheetId='$it'") }
            result.onFailure { println("$TAG getRemoteSheetsId → ERROR (REST): ${it.message}") }
        }
    }
}
