@Composable
fun CharacterDetailScreen(
    viewModel: CharacterDetailViewModel,
    mainActions: MainActions,
) {
    val display by viewModel.display.collectAsState()
    val typography = VortexTypography()
    val a11y = LocalStrings.current.a11y

    val density = LocalDensity.current
    val windowInfo = LocalWindowInfo.current
    val screenHeight = with(density) {
        val statusBar = WindowInsets.statusBars.getTop(density)
        val navBar = WindowInsets.navigationBars.getBottom(density)
        (windowInfo.containerSize.height - statusBar - navBar).toDp()
    }

    val consumeAllScroll = remember {
        object : NestedScrollConnection {
            override fun onPostScroll(
                consumed: Offset,
                available: Offset,
                source: NestedScrollSource,
            ): Offset = available
        }
    }

    LocalLifecycleOwner.current.onCreate {
        viewModel.initVM(mainActions)
    }

    when (val state = display) {
        is CharacterDetailScreenDisplay.Loading -> {
            Box(
                modifier = Modifier
                    .requiredHeight(screenHeight)
                    .fillMaxWidth()
                    .nestedScroll(consumeAllScroll)
                    .semantics {
                        liveRegion = LiveRegionMode.Polite
                        contentDescription = a11y.loading
                    },
                contentAlignment = Alignment.Center,
            ) {
                CircularProgressIndicator()
            }
        }

        is CharacterDetailScreenDisplay.Error -> {
            Box(
                modifier = Modifier
                    .requiredHeight(screenHeight)
                    .fillMaxWidth()
                    .padding(24.dp)
                    .nestedScroll(consumeAllScroll)
                    .semantics { liveRegion = LiveRegionMode.Assertive },
                contentAlignment = Alignment.Center,
            ) {
                Column(horizontalAlignment = Alignment.CenterHorizontally) {
                    Text(text = state.message, style = typography.bodyMedium)
                    androidx.compose.foundation.layout.Spacer(modifier = Modifier.height(16.dp))
                    Button(onClick = { viewModel.onEvent(CharacterDetailEvent.Retry) }) {
                        Text(text = state.retryButton)
                    }
                }
            }
        }

        is CharacterDetailScreenDisplay.Display -> {
            var showSettingsMenu by remember { mutableStateOf(false) }
            var showLogoutConfirmation by remember { mutableStateOf(false) }

            if (showLogoutConfirmation) {
                androidx.compose.material.AlertDialog(
                    onDismissRequest = { showLogoutConfirmation = false },
                    title = { Text(text = state.logoutButton, style = typography.headlineSmall) },
                    text = { Text(text = state.logoutConfirmMessage, style = typography.bodyMedium) },
                    confirmButton = {
                        Button(onClick = {
                            showLogoutConfirmation = false
                            viewModel.onEvent(CharacterDetailEvent.Logout)
                        }) {
                            Text(text = state.logoutConfirmButton)
                        }
                    },
                    dismissButton = {
                        Button(onClick = { showLogoutConfirmation = false }) {
                            Text(text = state.logoutCancelButton)
                        }
                    },
                )
            }

            Box(
                modifier = Modifier
                    .requiredHeight(screenHeight)
                    .fillMaxWidth()
                    .background(Color.White)
                    .nestedScroll(consumeAllScroll),
            ) {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .verticalScroll(rememberScrollState())
                        .padding(bottom = 72.dp),
                ) {
                    CharacterDetailContent(display = state, onEvent = viewModel::onEvent)
                }

                // Settings gear — top right
                Box(
                    modifier = Modifier
                        .align(Alignment.TopEnd)
                        .padding(end = 4.dp, top = 4.dp),
                ) {
                    IconButton(
                        onClick = { showSettingsMenu = true },
                        modifier = Modifier.semantics { contentDescription = a11y.settingsMenu },
                    ) {
                        Text(
                            text = "\u2699",
                            style = VortexTypography().headlineMedium,
                            color = Color(0xFF9B1B30),
                        )
                    }
                    DropdownMenu(
                        expanded = showSettingsMenu,
                        onDismissRequest = { showSettingsMenu = false },
                    ) {
                        DropdownMenuItem(onClick = {
                            showSettingsMenu = false
                            viewModel.onEvent(CharacterDetailEvent.SwitchCharacter)
                        }) {
                            Text(text = state.switchCharacterButton, style = typography.bodyMedium)
                        }
                        DropdownMenuItem(onClick = {
                            showSettingsMenu = false
                            showLogoutConfirmation = true
                        }) {
                            Text(text = state.logoutButton, style = typography.bodyMedium)
                        }
                    }
                }

                Row(
                    modifier = Modifier
                        .align(Alignment.BottomStart)
                        .padding(start = 16.dp, bottom = 16.dp),
                ) {
                    Button(
                        modifier = Modifier.height(50.dp),
                        onClick = { viewModel.onEvent(CharacterDetailEvent.Back) },
                    ) {
                        Text(text = state.backButton)
                    }
                }
            }
        }
    }
}
