package com.coding.va.selfhelp.data.mapper

import com.coding.va.selfhelp.data.models.EntryData
import com.coding.va.selfhelp.data.models.SheetsAppendResponse
import com.coding.va.selfhelp.domain.model.EntryType

import com.coding.va.selfhelp.domain.model.SheetEntryData


fun SheetsAppendResponse.toSheetsEntry(type: EntryType): SheetEntryData {
    val itemId = this.updates?.updatedRange?.updatedFieldToId(type)!!
    val rowNumber = this.updates.updatedRange.getRowNumber()
    return SheetEntryData(
        rowNumber = rowNumber,
        itemId = itemId,
        type = type,
        getCardCode = itemId.entryIdToGetCardCode(rowNumber, type),
        alreadyPrinted = false,
    )
}

private fun String.getRowNumber() = this.substringAfter("!A").substringBefore(":")

private fun String.entryIdToGetCardCode(rowNumber: String, type: EntryType): String {
    val chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
    val code = CharArray(3)

    // Use hashCode as a starting point
    var value = this.hashCode().toLong()

    // Generate 6 characters
    for (i in 0 until 3) {
        code[i] = chars[(value % 36).toInt()]
        value = (value * 31 + 17) and 0x7FFFFFFF // Simple transformation to mix bits
    }

    return "${intToBase36(rowNumber.toInt())}+${type.shortFix}${code.joinToString("")}"
}

@Throws(IllegalArgumentException::class)
fun String.cardCodeToEntryData(): EntryData {
    if (this.split("+").size != 2) {
        throw IllegalArgumentException("Invalid card code format")
    }
    val rowNumber = base36ToInt(this.substringBefore("+"))
    val sheetId = EntryType.entries.firstOrNull { it.shortFix == this.substringAfter("+").take(1) }
    return EntryData(
        rowNumber = rowNumber.toString(),
        type = sheetId ?: throw IllegalArgumentException("Invalid sheet ID")
    )
}

fun intToBase36(value: Int): String {
    if (value == 0) return "A"

    val chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
    val base = 36
    var num = if (value < 0) -value else value
    val result = StringBuilder()

    while (num > 0) {
        val remainder = num % base
        result.append(chars[remainder])
        num /= base
    }

    return if (value < 0) "-${result.reverse()}" else result.reverse().toString()
}

fun base36ToInt(base36: String): Int {
    val chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
    val base = 36
    var result = 0
    val isNegative = base36.startsWith("-")
    val cleanedInput = if (isNegative) base36.drop(1) else base36

    for (char in cleanedInput) {
        val value = chars.indexOf(char.uppercaseChar())
        if (value == -1) throw IllegalArgumentException("Invalid character: $char")
        result = result * base + value
    }

    return if (isNegative) -result else result
}

private fun String.updatedFieldToId(type: EntryType) =
    "${type.codePrefix}${(this.getRowNumber()).padStart(3, '0')}"

