package com.coding.va.selfhelp.utils

import kotlin.io.encoding.Base64
import kotlin.io.encoding.ExperimentalEncodingApi

/**
 * Minimal JWT decoder — only reads the payload (no signature verification).
 * Used to extract the `sub` claim (= plin) from the stored VOID access token.
 */
@OptIn(ExperimentalEncodingApi::class)
object JwtDecoder {

    /**
     * Decodes the JWT payload and returns the `sub` field as an [Int].
     * Returns null if the token is blank, malformed, or has no `sub` field.
     */
    fun extractPlin(jwt: String?): Int? {
        if (jwt.isNullOrBlank()) return null
        return try {
            val parts = jwt.split(".")
            if (parts.size < 2) return null

            // JWT uses base64url encoding (no padding). Normalise it.
            val base64url = parts[1].replace('-', '+').replace('_', '/')
            // Pad to multiple-of-4
            val padded = when (base64url.length % 4) {
                2 -> "$base64url=="
                3 -> "$base64url="
                else -> base64url
            }
            val decoded = Base64.decode(padded).decodeToString()

            // Simple regex extraction — avoids a full JSON parser dependency.
            val match = Regex(""""sub"\s*:\s*(\d+)""").find(decoded)
            match?.groupValues?.get(1)?.toIntOrNull()
        } catch (_: Exception) {
            null
        }
    }
}
