package com.coding.va.selfhelp.presentation.screens.history

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.coding.va.selfhelp.domain.use_cases.SavedCreationUseCase
import com.coding.va.selfhelp.i18n.AppStrings
import com.coding.va.selfhelp.presentation.screens.history.model.HistoryEvent
import com.coding.va.selfhelp.presentation.screens.history.model.HistoryScreenDisplay
import com.coding.va.selfhelp.presentation.screens.mainscreen.actions.MainActions
import com.coding.va.selfhelp.presentation.screens.mainscreen.destinations.MainDestinations
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import org.koin.android.annotation.KoinViewModel

@KoinViewModel
class HistoryViewModel(
    private val savedCreationUseCase: SavedCreationUseCase,
    private val strings: AppStrings,
) : ViewModel() {

    private val _display = MutableStateFlow<HistoryScreenDisplay>(HistoryDisplayProvider.provideLoading())
    val display = _display.asStateFlow()

    private var mainActions: MainActions? = null

    fun initVM(actions: MainActions) {
        mainActions = actions
        loadHistory()
    }

    private fun loadHistory() {
        viewModelScope.launch {
            val result = savedCreationUseCase.getSavedCreations()
            result
                .onSuccess { savedCreations ->
                    _display.emit(HistoryDisplayMapper.mapDisplay(savedCreations, strings))
                }
                .onFailure {
                    _display.emit(HistoryDisplayMapper.mapFailure(strings))
                }
        }
    }

    fun onEvent(event: HistoryEvent) {
        viewModelScope.launch {
            when (event) {
                is HistoryEvent.ToggleExpand -> {
                    val current = _display.value as? HistoryScreenDisplay.Display ?: return@launch
                    val updatedItems = current.items.mapIndexed { index, item ->
                        if (index == event.index) item.copy(isExpanded = !item.isExpanded) else item
                    }
                    _display.emit(current.copy(items = updatedItems))
                }

                is HistoryEvent.RepeatCreation -> {
                    val current = _display.value as? HistoryScreenDisplay.Display ?: return@launch
                    val item = current.items.getOrNull(event.index) ?: return@launch
                    val card = item.vortexCard
                    val energyStr = card?.energyUsed?.entries
                        ?.joinToString(",") { "${it.key.name}:${it.value}" }
                        .orEmpty()

                    val typeCode = item.cardCode.substringAfter("+", "").take(1)
                    val destination = when (typeCode) {
                        "1" -> {
                            val resourcesStr = card?.craftResources
                                ?.joinToString(";") { "${it.resourceAmount},${it.resourceType},${it.energyAmount},${it.energyType},${it.plin},${it.chin}" }
                                .orEmpty()
                            MainDestinations.CraftItem(
                                prefillDescription = card?.itemDescription.orEmpty(),
                                prefillImbueCap = card?.imbueCap.orEmpty(),
                                prefillEnergy = energyStr,
                                prefillResources = resourcesStr,
                                prefillNotes = item.notes.orEmpty(),
                            )
                        }
                        "2", "3" -> {
                            val imbueJson = card?.imbueResourceEntries?.let {
                                Json.encodeToString(it)
                            }.orEmpty()
                            MainDestinations.Imbue(
                                isPerson = typeCode == "3",
                                prefillEnergy = energyStr,
                                prefillImbueResources = imbueJson,
                                prefillNotes = item.notes.orEmpty(),
                            )
                        }
                        else -> return@launch
                    }
                    mainActions?.navigate(destination)
                }

                is HistoryEvent.Back -> {
                    mainActions?.home()
                }
            }
        }
    }
}
