package com.coding.va.selfhelp.presentation.screens.login.model

sealed class LoginScreenDisplay {
    data object Loading : LoginScreenDisplay()

    data class Display(
        val title: String,
        val providers: List<SocialProviderDisplay>,
        val googleButtonLabel: String,
        val appleButtonLabel: String,
        val isAuthenticating: Boolean,
        val backButton: String,
    ) : LoginScreenDisplay()

    data class Error(
        val title: String,
        val description: String,
        val retryButton: String,
        val backButton: String,
    ) : LoginScreenDisplay()

    data class LoggedIn(
        val title: String,
        val label: String,
        val backButton: String,
    ) : LoginScreenDisplay()
}

data class SocialProviderDisplay(
    /** Internal provider name returned by the VOID API (e.g. "discord", "google"). */
    val name: String,
    /** Button label shown to the user. */
    val buttonLabel: String,
)

sealed class LoginScreenEvent {
    data class LoginWithProvider(val providerName: String) : LoginScreenEvent()
    /** Trigger native Google Sign-In SDK flow (Android / iOS). */
    data object LoginWithGoogle : LoginScreenEvent()
    /** Trigger native Apple Sign-In flow (iOS only). */
    data object LoginWithApple : LoginScreenEvent()
    data object RetryLoad : LoginScreenEvent()
    data object Back : LoginScreenEvent()
}
