        bodyLarge = bodyLarge.copy(fontFamily = fontFamily, fontSize = 18.sp, fontWeight = FontWeight.Bold),
        bodyMedium = bodyMedium.copy(fontFamily = fontFamily, fontSize = 18.sp),
        bodySmall = bodySmall.copy(fontFamily = fontFamily, fontSize = 12.sp),
