package com.coding.va.selfhelp.presentation.components.errorbox

import androidx.compose.material.Text
import androidx.compose.material3.AlertDialog
import androidx.compose.material3.TextButton
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.semantics.LiveRegionMode
import androidx.compose.ui.semantics.liveRegion
import androidx.compose.ui.semantics.semantics
import com.coding.va.selfhelp.presentation.components.errorbox.model.ErrorBoxDisplay
import com.coding.va.selfhelp.theme.VortexTypography

@Composable
fun ErrorBox(
    onDismissRequest: () -> Unit,
    onConfirmation: () -> Unit,
    display: ErrorBoxDisplay
) {
    val typography = VortexTypography()
    AlertDialog(
        title = {
            Text(
                text = display.title,
                style = typography.titleLarge,
                modifier = Modifier.semantics { liveRegion = LiveRegionMode.Assertive },
            )
        },
        text = {
            Text(text = display.description, style = typography.bodyMedium)
        },
        onDismissRequest = {
            onDismissRequest()
        },
        confirmButton = {
            display.acceptButton?.let {
                TextButton(
                    onClick = {
                        onConfirmation()
                    }
                ) {
                    Text(display.acceptButton, style = typography.bodyLarge)
                }
            } ?: run {
                TextButton(
                    onClick = {
                        onDismissRequest()
                    }
                ) {
                    Text(display.retryButton, style = typography.bodyLarge)
                }
            }

        },
        dismissButton = {
            display.acceptButton?.let {
                TextButton(
                    onClick = {
                        onDismissRequest()
                    }
                ) {
                    Text(display.retryButton)
                }
            }
        }
    )
}