package com.coding.va.selfhelp.data.respository

import com.coding.va.selfhelp.data.mapper.toDomain
import com.coding.va.selfhelp.data.network.VoidCharactersApi
import com.coding.va.selfhelp.domain.model.ActiveCharacter
import com.coding.va.selfhelp.domain.model.CharacterDetail
import com.coding.va.selfhelp.domain.model.CharacterSummary
import com.coding.va.selfhelp.domain.model.EntityManaResult
import com.coding.va.selfhelp.domain.model.ItemTextDetail
import com.coding.va.selfhelp.domain.model.ProbeItemResult
import com.coding.va.selfhelp.domain.respository.CharactersRepository
import com.russhwolf.settings.Settings
import org.koin.core.annotation.Single

private const val SETTINGS_KEY_ACTIVE_PLIN = "void_plin"
private const val SETTINGS_KEY_ACTIVE_CHIN = "void_chin"

@Single
class CharactersRepositoryImp(
    private val api: VoidCharactersApi,
) : CharactersRepository {

    private val settings = Settings()

    override suspend fun getCharacters(plin: Int): Result<List<CharacterSummary>> =
        Result.runCatching {
            api.getCharacters(plin).map { it.toDomain() }
        }

    override suspend fun getCharacterDetail(plin: Int, chin: Int): Result<CharacterDetail> =
        Result.runCatching {
            api.getCharacterDetail(plin, chin).toDomain()
        }

    override suspend fun getConditionPlayerText(coin: Int): Result<String?> =
        Result.runCatching { api.getConditionDetail(coin).playerText }

    override suspend fun getPowerPlayerText(poin: Int): Result<String?> =
        Result.runCatching { api.getPowerDetail(poin).playerText }

    override suspend fun getConditionMana(coin: Int): Result<EntityManaResult> =
        Result.runCatching {
            val detail = api.getConditionDetail(coin)
            EntityManaResult(manaAmount = detail.manaAmount, manatypeName = detail.manatype?.name)
        }

    override suspend fun getPowerMana(poin: Int): Result<EntityManaResult> =
        Result.runCatching {
            val detail = api.getPowerDetail(poin)
            EntityManaResult(manaAmount = detail.manaAmount, manatypeName = detail.manatype?.name)
        }

    override suspend fun getItemMana(itin: Int): Result<EntityManaResult> =
        Result.runCatching {
            val detail = api.getItemDetail(itin)
            EntityManaResult(
                manaAmount = detail.manaAmount,
                manatypeName = detail.manatype?.name,
                imbueCapacity = detail.imbueCapacity,
            )
        }

    override suspend fun getItemDetails(itin: Int): Result<ItemTextDetail> =
        Result.runCatching {
            val entity = api.getItemDetail(itin)
            ItemTextDetail(description = entity.description, playerText = entity.playerText)
        }

    override suspend fun probeItem(itin: Int): Result<ProbeItemResult> =
        Result.runCatching {
            val entity = api.getItemDetail(itin)
            ProbeItemResult(
                itin = entity.itin,
                name = entity.name,
                description = entity.description,
                playerText = entity.playerText,
                ownerPlin = entity.plin,
                ownerChin = entity.chin,
                ownerCharacterName = entity.character?.name,
            )
        }

    override fun saveActiveCharacter(plin: Int, chin: Int) {
        settings.putInt(SETTINGS_KEY_ACTIVE_PLIN, plin)
        settings.putInt(SETTINGS_KEY_ACTIVE_CHIN, chin)
    }

    override fun clearActiveCharacter() {
        settings.remove(SETTINGS_KEY_ACTIVE_PLIN)
        settings.remove(SETTINGS_KEY_ACTIVE_CHIN)
    }

    override fun getActiveCharacter(): ActiveCharacter? {
        val plin = settings.getIntOrNull(SETTINGS_KEY_ACTIVE_PLIN) ?: return null
        val chin = settings.getIntOrNull(SETTINGS_KEY_ACTIVE_CHIN) ?: return null
        return ActiveCharacter(plin = plin, chin = chin)
    }

}
