import com.coding.va.selfhelp.i18n.localizedEffect
import com.coding.va.selfhelp.i18n.localizedName
import com.coding.va.selfhelp.i18n.localizedRequiredSkill
import com.coding.va.selfhelp.presentation.components.Button
import com.coding.va.selfhelp.presentation.components.OutlinedTextField
import com.coding.va.selfhelp.presentation.components.errorbox.ErrorBox
import com.coding.va.selfhelp.presentation.components.moveFocusOnTab
import com.coding.va.selfhelp.presentation.components.onlyDesktop
import com.coding.va.selfhelp.presentation.components.plinfield.PlinTextField
import com.coding.va.selfhelp.presentation.components.selectablefield.SelectableField
import com.coding.va.selfhelp.presentation.screens.mundane.model.MundaneDisplay
import com.coding.va.selfhelp.presentation.screens.mundane.model.MundaneEvent
import com.coding.va.selfhelp.presentation.screens.mundane.model.MundaneInspirationSupplier
import com.coding.va.selfhelp.presentation.screens.mundane.model.isCrafterPlinValid
import com.coding.va.selfhelp.presentation.screens.mundane.model.hasAnyInspirationSupplied
import com.coding.va.selfhelp.presentation.screens.mundane.model.isFilled
import com.coding.va.selfhelp.presentation.screens.mundane.model.isInspirationTotalValid
import com.coding.va.selfhelp.presentation.screens.mundane.model.isValid
import com.coding.va.selfhelp.presentation.screens.mundane.model.requiredInspirationTotal
import com.coding.va.selfhelp.presentation.screens.mundane.model.totalInspirationSupplied
import com.coding.va.selfhelp.presentation.screens.mundane.model.isQuantityValid
import com.coding.va.selfhelp.presentation.screens.mundane.model.isSkillSelected
import com.coding.va.selfhelp.presentation.screens.mundane.model.isTargetPlin2Valid
import com.coding.va.selfhelp.presentation.screens.mundane.model.isTargetPlinValid
import com.coding.va.selfhelp.presentation.screens.verify.VerifySheet
