import com.coding.va.selfhelp.theme.successGreen

@OptIn(ExperimentalLayoutApi::class)
@Composable
fun MundaneContent(
    display: MundaneDisplay,
    onEvent: ((MundaneEvent) -> Unit)? = null,
) {
    val numberRegex = remember { Regex("^\\d+$") }
    val typography = VortexTypography()
    val strings = LocalStrings.current
    val numericKeyboard = KeyboardOptions(keyboardType = KeyboardType.Number)

    Surface(modifier = Modifier.fillMaxSize().background(Color.White)) {
        display.errorBox?.let {
            ErrorBox(
                display = it,
                onConfirmation = { onEvent?.invoke(MundaneEvent.Confirm) },
                onDismissRequest = { onEvent?.invoke(MundaneEvent.DismissError) },
            )
        }

        display.verifySheet?.let {
            VerifySheet(
                display = it,
                onConfirm = { onEvent?.invoke(MundaneEvent.Confirm) },
                onDismiss = { onEvent?.invoke(MundaneEvent.DismissError) },
            )
        }

        Box(modifier = Modifier.fillMaxSize()) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .verticalScroll(rememberScrollState())
                    .padding(start = 24.dp, top = 24.dp, end = 24.dp, bottom = 80.dp)
            ) {
            Text(
                text = display.title,
                style = typography.headlineLarge,
                modifier = Modifier.semantics { heading() },
            )
            Text(text = display.description, style = typography.titleLarge)

            Column(modifier = Modifier.padding(top = 24.dp)) {

                // ── Skill selector ──────────────────────────────────────────
                SelectableField(
                    modifier = Modifier.width(300.dp).moveFocusOnTab(),
                    isError = display.shouldValidate && !display.form.isSkillSelected(),
                    display = display.skillField,
                    value = display.form.selectedSkill?.localizedName(LocalStrings.current),
                    onSelected = { content ->
                        val skill = MundaneSkill.entries.firstOrNull { it.name == content.id }
                        onEvent?.invoke(
                            MundaneEvent.UpdateForm(
                                display.form.copy(selectedSkill = skill)
                            )
                        )
                    }
                )

                // ── Info box for selected skill ──────────────────────────────
                display.form.selectedSkill?.let { skill ->
                    Column(
                        modifier = Modifier
                            .padding(top = 16.dp)
                            .width(600.dp)
                            .border(2.dp, Color.Black, RoundedCornerShape(8.dp))
                            .padding(12.dp)
                    ) {
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            Text(
                                text = display.skillRequiredLabel,
                                style = typography.bodyMedium,
                                modifier = Modifier.width(140.dp)
                            )
                            Text(text = skill.localizedRequiredSkill(LocalStrings.current), style = typography.bodyLarge)
                        }
                        Spacer(modifier = Modifier.height(4.dp))
                        Row(verticalAlignment = Alignment.Top) {
                            Text(
                                text = display.skillResourcesLabel,
                                style = typography.bodyMedium,
                                modifier = Modifier.width(140.dp)
                            )
                            Text(text = skill.resources, style = typography.bodyLarge)
                        }
                        Spacer(modifier = Modifier.height(4.dp))
                        Row(verticalAlignment = Alignment.Top) {
                            Text(
                                text = display.skillEffectLabel,
                                style = typography.bodyMedium,
                                modifier = Modifier.width(140.dp)
                            )
                            Text(text = skill.localizedEffect(LocalStrings.current), style = typography.bodyMedium)
                        }
                    }
                }

                Spacer(modifier = Modifier.height(16.dp))

                // ── Quantity (Scroll Paper only) ─────────────────────────────
                if (display.form.selectedSkill?.hasQuantity == true) {
                    val qtyInvalid = display.shouldValidate && !display.form.isQuantityValid()
                    OutlinedTextField(
                        modifier = Modifier.width(150.dp).moveFocusOnTab(),
                        isError = qtyInvalid,
                        errorText = if (qtyInvalid) strings.a11y.errorNumbersOnly else null,
                        keyboardOptions = numericKeyboard,
                        value = display.form.quantity,
                        placeholder = { Text(text = display.quantityField.hint) },
                        onValueChange = { input ->
                            if (input.isEmpty() || input.matches(numberRegex)) {
                                onEvent?.invoke(
                                    MundaneEvent.UpdateForm(display.form.copy(quantity = input))
                                )
                            }
                        },
                        label = { Text(text = display.quantityField.label) },
                    )
                    Spacer(modifier = Modifier.height(8.dp))
                }

                // ── Crafter PLIN ─────────────────────────────────────────────
                PlinTextField(
                    display = display.crafterPlinField,
                    isError = display.shouldValidate && !display.form.isCrafterPlinValid(),
                    errorText = if (display.shouldValidate && !display.form.isCrafterPlinValid()) strings.a11y.errorInvalidPlin else null,
                    value = display.form.crafterPlin,
                    onValueChange = { plin ->
                        onEvent?.invoke(
                            MundaneEvent.UpdateForm(display.form.copy(crafterPlin = plin))
                        )
                    },
                )

                Spacer(modifier = Modifier.height(8.dp))

                // ── Target PLIN (if required) ────────────────────────────────
                if (display.form.selectedSkill?.requiresTargetPlin == true) {
                    PlinTextField(
                        display = display.targetPlinField,
                        isError = display.shouldValidate && !display.form.isTargetPlinValid(),
                        value = display.form.targetPlin,
                        onValueChange = { plin ->
                            onEvent?.invoke(
                                MundaneEvent.UpdateForm(display.form.copy(targetPlin = plin))
                            )
                        },
                    )
                    Spacer(modifier = Modifier.height(8.dp))
                }

                // ── Second PLIN (Marriage Jewelry only) ──────────────────────
                if (display.form.selectedSkill?.requiresSecondPlin == true) {
                    PlinTextField(
                        display = display.targetPlin2Field,
                        isError = display.shouldValidate && !display.form.isTargetPlin2Valid(),
                        value = display.form.targetPlin2,
                        onValueChange = { plin ->
                            onEvent?.invoke(
                                MundaneEvent.UpdateForm(display.form.copy(targetPlin2 = plin))
                            )
                        },
                    )
                    Spacer(modifier = Modifier.height(8.dp))
                }

                Spacer(modifier = Modifier.height(8.dp))

                // ── Notes ────────────────────────────────────────────────────
                OutlinedTextField(
                    modifier = Modifier.height(100.dp).width(350.dp).moveFocusOnTab(),
                    value = display.form.notes,
                    placeholder = { Text(text = display.notesField.hint) },
                    onValueChange = { notes ->
                        onEvent?.invoke(
                            MundaneEvent.UpdateForm(display.form.copy(notes = notes))
                        )
                    },
                    label = { Text(text = display.notesField.label) },
                )

                Spacer(modifier = Modifier.height(16.dp))

                // ── Who is supplying Inspiration? (optional) ─────────────────
                Text(
                    text = display.inspirationSectionTitle,
                    style = typography.bodyLarge,
                )
                Text(
                    modifier = Modifier.padding(top = 4.dp, bottom = 4.dp),
                    text = display.inspirationSupplierDescription,
                    style = typography.bodyMedium,
                )
                if (display.form.hasAnyInspirationSupplied()) {
                    val supplied = display.form.totalInspirationSupplied()
                    val required = display.form.requiredInspirationTotal()
                    val totalOk = display.form.isInspirationTotalValid()
                    // Glyph is a non-color signal so users who can't distinguish red from
                    // green still know whether the total is valid (WCAG 1.4.1).
                    val glyph = if (totalOk) "✓ " else "✗ "
                    Text(
                        modifier = Modifier
                            .padding(bottom = 12.dp)
                            .semantics { liveRegion = LiveRegionMode.Polite },
                        text = glyph + display.inspirationCountLabel + "$supplied / $required",
                        style = typography.bodyMedium,
                        color = if (!totalOk) Color.Red else successGreen,
                    )
                } else {
                    Spacer(modifier = Modifier.height(8.dp))
                }

                display.form.inspirationSuppliers.forEach { (key, supplier) ->
                    Row(verticalAlignment = Alignment.Bottom) {
                        FlowRow(
                            modifier = Modifier
                                .border(3.dp, secondaryTextColor, RoundedCornerShape(8.dp))
                                .padding(top = 16.dp, start = 16.dp, end = 16.dp, bottom = 20.dp),
                        ) {
                            OutlinedTextField(
                                modifier = Modifier.width(120.dp).padding(end = 8.dp).moveFocusOnTab(),
                                isError = display.shouldValidate && supplier.isFilled() && !supplier.isValid(),
                                errorText = if (display.shouldValidate && supplier.isFilled() && !supplier.isValid()) strings.a11y.errorNumbersOnly else null,
                                keyboardOptions = numericKeyboard,
                                value = supplier.amount,
                                placeholder = { Text(text = display.inspirationSupplierAmountField.hint) },
                                onValueChange = { input ->
                                    if (input.isEmpty() || input.matches(numberRegex)) {
                                        onEvent?.invoke(
                                            MundaneEvent.UpdateForm(
                                                display.form.copy(
                                                    inspirationSuppliers = display.form.inspirationSuppliers
                                                        .toMutableMap()
                                                        .apply { this[key] = supplier.copy(amount = input) }
                                                )
                                            )
                                        )
                                    }
                                },
                                label = { Text(text = display.inspirationSupplierAmountField.label) },
                            )

                            PlinTextField(
                                display = display.inspirationSupplierPlinField,
                                isError = display.shouldValidate && supplier.isFilled() && !supplier.isValid(),
                                errorText = if (display.shouldValidate && supplier.isFilled() && !supplier.isValid()) strings.a11y.errorInvalidPlin else null,
                                modifier = Modifier.padding(start = 8.dp).moveFocusOnTab(),
                                value = supplier.plin,
                                onValueChange = { plin ->
                                    onEvent?.invoke(
                                        MundaneEvent.UpdateForm(
                                            display.form.copy(
                                                inspirationSuppliers = display.form.inspirationSuppliers
                                                    .toMutableMap()
                                                    .apply { this[key] = supplier.copy(plin = plin) }
                                            )
                                        )
                                    )
                                },
                            )
                        }

                        // + / - buttons only on the last row
                        if (display.form.inspirationSuppliers.size == key) {
                            FlowRow {
                                if (key > 1) {
                                    Button(
                                        modifier = Modifier
                                            .padding(top = 10.dp, start = 12.dp)
                                            .height(50.dp)
                                            .width(50.dp)
                                            .semantics { contentDescription = strings.a11y.removeRow },
                                        onClick = { onEvent?.invoke(MundaneEvent.RemoveInspirationSupplier(key)) },
                                    ) {
                                        Text(text = "-")
                                    }
                                }
                                Button(
                                    modifier = Modifier
                                        .padding(top = 10.dp, start = 12.dp)
                                        .height(50.dp)
                                        .width(50.dp)
                                        .semantics { contentDescription = strings.a11y.addRow },
                                    onClick = { onEvent?.invoke(MundaneEvent.AddInspirationSupplier(key)) },
                                ) {
                                    Text(text = "+")
                                }
                            }
                        }
                    }
                    Spacer(modifier = Modifier.height(8.dp))
                }
            }

            } // end scrollable Column

            // ── Action buttons ───────────────────────────────────────────────
            Row(
                modifier = Modifier
                    .align(Alignment.BottomCenter)
                    .fillMaxWidth()
                    .padding(start = 24.dp, end = 24.dp, top = 8.dp, bottom = 16.dp)
            ) {
                Button(
                    modifier = Modifier.height(50.dp).onlyDesktop { width(200.dp) },
                    onClick = { onEvent?.invoke(MundaneEvent.Back) },
                ) {
                    Text(text = display.backButton)
                }
                Spacer(modifier = Modifier.weight(1f))
                Button(
                    modifier = Modifier.height(50.dp).onlyDesktop { width(200.dp) },
                    onClick = { onEvent?.invoke(MundaneEvent.Verify) },
                ) {
                    Text(text = display.nextButton)
                }
            }
        } // end Box
    }
}
