package com.coding.va.selfhelp.data.mapper

import com.coding.va.selfhelp.data.models.CharacterConditionEntity
import com.coding.va.selfhelp.data.models.CharacterDetailEntity
import com.coding.va.selfhelp.data.models.CharacterGlyphImbueEntity
import com.coding.va.selfhelp.data.models.CharacterItemEntity
import com.coding.va.selfhelp.data.models.CharacterPowerEntity
import com.coding.va.selfhelp.data.models.CharacterRuneImbueEntity
import com.coding.va.selfhelp.data.models.CharacterSkillEntity
import com.coding.va.selfhelp.data.models.CharacterSummaryEntity
import com.coding.va.selfhelp.domain.model.CharacterCondition
import com.coding.va.selfhelp.domain.model.CharacterDetail
import com.coding.va.selfhelp.domain.model.CharacterGlyphImbue
import com.coding.va.selfhelp.domain.model.CharacterItem
import com.coding.va.selfhelp.domain.model.CharacterPower
import com.coding.va.selfhelp.domain.model.CharacterRuneImbue
import com.coding.va.selfhelp.domain.model.CharacterSkill
import com.coding.va.selfhelp.domain.model.CharacterSummary

fun CharacterSummaryEntity.toDomain() = CharacterSummary(
    plin = plin,
    chin = chin,
    name = name,
    status = status,
)

fun CharacterDetailEntity.toDomain() = CharacterDetail(
    plin = plin,
    chin = chin,
    name = name,
    xp = xp,
    belief = belief,
    group = group,
    world = world,
    status = status,
    faction = faction,
    items = items.list.map { it.toDomain() },
    conditions = conditions.list.map { it.toDomain() },
    powers = powers.list.map { it.toDomain() },
    skills = skills.list.map { it.toDomain() },
    runeImbues = runeimbues.list.map { it.toDomain() },
    glyphImbues = glyphimbues.list.map { it.toDomain() },
)

fun CharacterItemEntity.toDomain() = CharacterItem(
    itin = itin,
    name = name,
    expiry = expiry,
    deprecated = deprecated,
)

fun CharacterConditionEntity.toDomain() = CharacterCondition(
    coin = condition.coin,
    name = condition.name,
    expiry = expiry,
    deprecated = condition.deprecated,
)

fun CharacterPowerEntity.toDomain() = CharacterPower(
    poin = power.poin,
    name = power.name,
    expiry = expiry,
    deprecated = power.deprecated,
)

fun CharacterSkillEntity.toDomain() = CharacterSkill(
    id = skill.id,
    name = skill.name,
    times = times,
    cost = skill.cost,
    manaAmount = skill.manaAmount,
    manatypeName = skill.manatype?.name,
    loresheet = skill.loresheet,
    deprecated = skill.deprecated,
)

fun CharacterRuneImbueEntity.toDomain() = CharacterRuneImbue(
    name = name,
    expiry = expiry,
)

fun CharacterGlyphImbueEntity.toDomain() = CharacterGlyphImbue(
    name = name,
    expiry = expiry,
)
