package com.coding.va.selfhelp.data.network

import co.touchlab.kermit.Logger
import com.coding.va.selfhelp.data.models.AuthTokenEntity
import com.coding.va.selfhelp.data.models.SocialProviderEntity
import com.coding.va.selfhelp.data.models.SocialProvidersResponse
import com.coding.va.selfhelp.domain.exceptions.AccountNotLinkedException
import io.ktor.client.HttpClient
import io.ktor.client.call.body
import io.ktor.client.request.get
import io.ktor.client.request.parameter
import io.ktor.client.statement.bodyAsText
import io.ktor.http.isSuccess

import org.koin.core.annotation.Named
import org.koin.core.annotation.Single
import com.coding.va.selfhelp.data.di.VOID_CLIENT

private val log = Logger.withTag("VoidAuthApi")

@Single
class VoidAuthApiImp(@Named(VOID_CLIENT) private val client: HttpClient) : VoidAuthApi {

    override suspend fun getSocialProviders(): List<SocialProviderEntity> {
        log.d { "Login - GET /auth/OAuth2" }
        val response = client.get("/auth/OAuth2")
        log.d { "Login - GET /auth/OAuth2 → status=${response.status}" }
        val wrapper = response.body<SocialProvidersResponse>()
        log.d { "Login - Providers parsed: ${wrapper.list.map { "${it.name} url=${it.url}" }}" }
        return wrapper.list
    }

    override suspend fun exchangeCode(url: String): String {
        log.d { "Login - exchangeCode GET: ${url.take(100)}…" }
        val response = client.get(url)
        log.d { "Login - exchangeCode response status: ${response.status}" }
        if (!response.status.isSuccess()) {
            val text = response.bodyAsText().trim()
            text.chunked(500).forEachIndexed { i, chunk ->
                log.d { "Login - exchangeCode error body [$i]: $chunk" }
            }
            if (response.status.value == 403) throw AccountNotLinkedException()
            throw Exception("Code exchange failed: ${response.status}")
        }
        val entity = response.body<AuthTokenEntity>()
        log.d { "Login - exchangeCode parsed entity: token=${entity.token?.take(12)} jwt=${entity.jwt?.take(12)} accessToken=${entity.accessToken?.take(12)}" }
        return entity.extractToken() ?: throw Exception("No token field found in response")
    }

    override suspend fun loginWithGoogleToken(idToken: String): String {
        log.d { "Login - loginWithGoogleToken GET /auth/OpenIDConnect/google?token=…" }
        val response = client.get("/auth/OpenIDConnect/google") {
            parameter("token", idToken)
        }
        log.d { "Login - loginWithGoogleToken response status: ${response.status}" }
        if (!response.status.isSuccess()) {
            val text = response.bodyAsText().trim()
            text.chunked(500).forEachIndexed { i, chunk ->
                log.d { "Login - loginWithGoogleToken error body [$i]: $chunk" }
            }
            if (response.status.value == 403) throw AccountNotLinkedException()
            throw Exception("Google login failed: ${response.status}")
        }
        val entity = response.body<AuthTokenEntity>()
        log.d { "Login - loginWithGoogleToken parsed entity: token=${entity.token?.take(12)} jwt=${entity.jwt?.take(12)}" }
        return entity.extractToken() ?: throw Exception("No token field found in /auth/login response")
    }

    override suspend fun loginWithAppleToken(idToken: String): String {
        log.d { "Login - loginWithAppleToken GET /auth/OpenIDConnect/apple?token=…" }
        val response = client.get("/auth/OpenIDConnect/apple") {
            parameter("token", idToken)
        }
        log.d { "Login - loginWithAppleToken response status: ${response.status}" }
        if (!response.status.isSuccess()) {
            val text = response.bodyAsText().trim()
            text.chunked(500).forEachIndexed { i, chunk ->
                log.d { "Login - loginWithAppleToken error body [$i]: $chunk" }
            }
            if (response.status.value == 403) throw AccountNotLinkedException()
            throw Exception("Apple login failed: ${response.status}")
        }
        val entity = response.body<AuthTokenEntity>()
        log.d { "Login - loginWithAppleToken parsed entity: token=${entity.token?.take(12)} jwt=${entity.jwt?.take(12)}" }
        return entity.extractToken() ?: throw Exception("No token field found in /auth/login/apple response")
    }
}
