package com.coding.va.selfhelp.domain.use_cases

import com.coding.va.selfhelp.domain.respository.AuthRepository
import org.koin.core.annotation.Factory

/**
 * Exchanges a Google ID token (obtained from the native Google Sign-In SDK) for an
 * app JWT by calling the backend's `/auth/login?token=` endpoint.
 *
 * The JWT is stored via [AuthRepository] on success.
 *
 * @param idToken The Google ID token string returned by the native sign-in SDK.
 * @return The app JWT string on success.
 */
@Factory
class LoginWithGoogleUseCase(private val repository: AuthRepository) {

    suspend operator fun invoke(idToken: String): Result<String> =
        repository.loginWithGoogle(idToken)
}
