package com.coding.va.selfhelp.presentation.screens.mainscreen

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.coding.va.selfhelp.di.getPlatform
import com.coding.va.selfhelp.domain.constants.Constants
import com.coding.va.selfhelp.domain.use_cases.GetRemoteSheetId
import com.coding.va.selfhelp.utils.Screens
import com.coding.va.selfhelp.utils.TYPE
import com.russhwolf.settings.Settings
import kotlinx.coroutines.delay
import kotlinx.coroutines.launch
import org.koin.android.annotation.KoinViewModel

private const val TAG = "[MainViewModel]"

@KoinViewModel
class MainViewModel(
    val getRemoteSheetId: GetRemoteSheetId
) : ViewModel() {

    private val settings = Settings()
    var screens by mutableStateOf(Screens.MAIN)
    var currentPos by mutableStateOf(-1)

    companion object {
        private const val DEFAULT_SHEET = "1nwPa67RHCGiAXmwKMOg_4ueopG3gPZ9hyUERMdSX3yg"
    }

    init {
        println("$TAG init — platform=${getPlatform()}")

        viewModelScope.launch {
            println("$TAG Waiting 2s before fetching Remote Config sheet ID...")
            delay(2000)
            println("$TAG Fetching Remote Config sheet ID now...")
            val result = getRemoteSheetId()
            val sheetId = result.getOrNull() ?: DEFAULT_SHEET
            println(
                "$TAG Remote Config result: ${
                    result.fold(
                        { "SUCCESS → sheetId='$it'" },
                        { "FAILURE → ${it.message}, using default" }
                    )
                }"
            )
            settings.putString(Constants.SETTINGS_KEY_SHEET_ID, sheetId)
        }

        if (settings.getString(Constants.SETTINGS_KEY_PRINTER_IP, "") == "") {
            settings.putString(Constants.SETTINGS_KEY_PRINTER_IP, "192.168.2.75")
        }

        if (settings.getString(Constants.SETTINGS_KEY_PRINTER_MODE, "") == "") {
            settings.putString(Constants.SETTINGS_KEY_PRINTER_MODE, "usb")
        }

        if (getPlatform() != TYPE.DESKTOP) {
            settings.putBoolean(Constants.SETTINGS_KEY_PRINTER_ENABLED, false)
        }
    }
}
