private val vortexRed = Color(0xFF9B1B30)

@Composable
fun CharacterDetailContent(
    display: CharacterDetailScreenDisplay.Display,
    onEvent: (CharacterDetailEvent) -> Unit,
) {
    val typography = VortexTypography()
    val tabs = listOf(
        display.tabSkills,
        display.tabConditions,
        display.tabItems,
        display.tabPowers,
    )
    var selectedTabIndex by remember { mutableStateOf(0) }

    Column(modifier = Modifier.fillMaxWidth()) {
        // -- Header info --
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 16.dp, vertical = 12.dp),
            verticalArrangement = Arrangement.spacedBy(4.dp),
        ) {
            Text(
                text = display.name,
                style = typography.headlineLarge,
                modifier = Modifier.semantics { heading() },
            )
            Spacer(Modifier.height(4.dp))
            InfoRow(label = display.statusLabel, value = display.status)
            display.faction?.let { InfoRow(label = display.factionLabel, value = it) }
            display.xp?.let { InfoRow(label = display.xpLabel, value = it) }
            display.belief?.let { InfoRow(label = display.beliefLabel, value = it) }
            display.group?.let { InfoRow(label = display.groupLabel, value = it) }
            display.world?.let { InfoRow(label = display.worldLabel, value = it) }

            // Energy totals section
            Spacer(Modifier.height(6.dp))
            EnergySection(
                label = display.energyLabel,
                totals = display.energyTotals,
            )
        }

        Divider(color = dividerColor)

        // -- Tabs --
        ScrollableTabRow(
            selectedTabIndex = selectedTabIndex,
            backgroundColor = Color.White,
            contentColor = vortexRed,
            edgePadding = 0.dp,
        ) {
            tabs.forEachIndexed { index, title ->
                Tab(
                    selected = selectedTabIndex == index,
                    onClick = { selectedTabIndex = index },
                    text = {
                        Text(
                            text = title,
                            style = typography.bodySmall,
                            fontWeight = if (selectedTabIndex == index) FontWeight.Bold else FontWeight.Normal,
                        )
                    },
                )
            }
        }

        Spacer(Modifier.height(8.dp))

        // -- Tab content --
        when (selectedTabIndex) {
            0 -> SkillsTab(display.skills, display.emptySkills, onEvent)
            1 -> ConditionsTab(display.conditions, display.emptyConditions, onEvent)
            2 -> ItemsTab(display.items, display.emptyItems, onEvent)
            3 -> PowersTab(
                powers = display.powers,
                runeImbues = display.runeImbues,
                glyphImbues = display.glyphImbues,
                powersHeader = display.powersHeader,
                runeImbuesHeader = display.runeImbuesHeader,
                glyphImbuesHeader = display.glyphImbuesHeader,
                emptyMessage = display.emptyPowers,
                onEvent = onEvent,
            )
        }
    }
}

// ---------------------------------------------------------------------------
// Info row
// ---------------------------------------------------------------------------

@Composable
private fun InfoRow(label: String, value: String) {
    val typography = VortexTypography()
    Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
        Text(
            text = "$label:",
            style = typography.bodySmall,
            color = secondaryTextColor,
            fontWeight = FontWeight.Medium,
        )
        Text(text = value, style = typography.bodySmall)
    }
}

// ---------------------------------------------------------------------------
// Energy section — shown in the overview header
// ---------------------------------------------------------------------------

@Composable
private fun EnergySection(label: String, totals: List<EnergyTotalDisplay>?) {
    val typography = VortexTypography()
    Row(
        modifier = Modifier.fillMaxWidth(),
        verticalAlignment = Alignment.Top,
        horizontalArrangement = Arrangement.spacedBy(6.dp),
    ) {
        Text(
            text = "$label:",
            style = typography.bodySmall,
            color = secondaryTextColor,
            fontWeight = FontWeight.Medium,
        )
        when {
            totals == null -> {
                // Still loading
                CircularProgressIndicator(
                    modifier = Modifier.size(12.dp),
                    strokeWidth = 1.5.dp,
                    color = vortexRed,
                )
            }
            totals.isEmpty() -> {
                Text(text = "—", style = typography.bodySmall, color = secondaryTextColor)
            }
            else -> {
                // Wrap chips in a flow-like column
                Column(verticalArrangement = Arrangement.spacedBy(2.dp)) {
                    totals.forEach { entry ->
                        Row(horizontalArrangement = Arrangement.spacedBy(4.dp)) {
                            Text(
                                text = "•",
                                style = typography.bodySmall,
                                color = vortexRed,
                            )
                            Text(
                                text = "${entry.manatypeName}: ${entry.total}",
                                style = typography.bodySmall,
                                color = Color(0xFF222222),
                            )
                        }
                    }
                }
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Skills tab — tap to expand inline details (cost, mana, loresheet)
// ---------------------------------------------------------------------------

@Composable
private fun SkillsTab(
    skills: List<CharacterSkillDisplay>,
    emptyMessage: String,
    onEvent: (CharacterDetailEvent) -> Unit,
) {
    val typography = VortexTypography()
    if (skills.isEmpty()) {
        Text(
            text = emptyMessage,
            style = typography.bodyMedium,
            color = secondaryTextColor,
            modifier = Modifier.padding(16.dp),
        )
        return
    }
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .padding(horizontal = 16.dp),
        verticalArrangement = Arrangement.spacedBy(8.dp),
    ) {
        skills.forEach { skill ->
            SkillRow(skill, onToggle = { onEvent(CharacterDetailEvent.ExpandSkill(skill.id)) })
        }
    }
}

@Composable
private fun SkillRow(skill: CharacterSkillDisplay, onToggle: () -> Unit) {
    val typography = VortexTypography()
    val a11y = LocalStrings.current.a11y
    val hasDetails = skill.cost > 0 || skill.manaAmount != null || skill.loresheet
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .background(Color(0xFFF8F8F8), RoundedCornerShape(6.dp)),
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .then(
                    if (hasDetails) Modifier
                        .semantics {
                            role = Role.Button
                            stateDescription = if (skill.isExpanded) a11y.expanded else a11y.collapsed
                        }
                        .clickable(onClick = onToggle)
                    else Modifier
                )
                .padding(10.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.SpaceBetween,
        ) {
            Text(
                text = if (skill.times > 1) "${skill.times}${skill.timesLabel} ${skill.name}"
                else skill.name,
                style = typography.bodyMedium,
                fontWeight = FontWeight.SemiBold,
                modifier = Modifier.weight(1f),
            )
            if (hasDetails) {
                Text(
                    text = if (skill.isExpanded) "▲" else "▼",
                    style = typography.bodySmall,
                    color = vortexRed,
                )
            }
        }

        AnimatedVisibility(
            visible = skill.isExpanded,
            enter = expandVertically(),
            exit = shrinkVertically(),
        ) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(start = 10.dp, end = 10.dp, bottom = 10.dp),
                verticalArrangement = Arrangement.spacedBy(4.dp),
            ) {
                Divider(color = dividerColor)
                Spacer(Modifier.height(2.dp))
                if (skill.cost > 0) {
                    Text(
                        text = "${skill.costLabel}: ${skill.cost} XP",
                        style = typography.bodySmall,
                        color = Color(0xFF444444),
                    )
                }
                if (skill.manaAmount != null && skill.manatypeName != null) {
                    Text(
                        text = "${skill.manaLabel}: ${skill.manaAmount} ${skill.manatypeName}",
                        style = typography.bodySmall,
                        color = Color(0xFF444444),
                    )
                }
                if (skill.loresheet) {
                    if (skill.loresheetUrl != null) {
                        Text(
                            text = "✦ ${skill.loresheetLabel}",
                            style = typography.bodySmall,
                            color = vortexRed,
                            textDecoration = TextDecoration.Underline,
                            modifier = Modifier.clickable { openInAppBrowser(skill.loresheetUrl) },
                        )
                    } else {
                        Text(
                            text = "✦ ${skill.loresheetLabel}",
                            style = typography.bodySmall,
                            color = vortexRed,
                        )
                    }
                }
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Conditions tab
// ---------------------------------------------------------------------------

@Composable
private fun ConditionsTab(
    conditions: List<CharacterConditionDisplay>,
    emptyMessage: String,
    onEvent: (CharacterDetailEvent) -> Unit,
) {
    val typography = VortexTypography()
    if (conditions.isEmpty()) {
        Text(
            text = emptyMessage,
            style = typography.bodyMedium,
            color = secondaryTextColor,
            modifier = Modifier.padding(16.dp),
        )
        return
    }
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .padding(horizontal = 16.dp),
        verticalArrangement = Arrangement.spacedBy(8.dp),
    ) {
        conditions.forEach { condition ->
            ExpandableEntryRow(
                name = condition.name,
                expiry = condition.expiry,
                expiryLabel = condition.expiryLabel,
                noExpiry = condition.noExpiry,
                isExpanded = condition.isExpanded,
                isLoadingDetail = condition.isLoadingDetail,
                playerText = condition.playerText,
                manaAmount = condition.manaAmount,
                manatypeName = condition.manatypeName,
                onToggle = { onEvent(CharacterDetailEvent.ExpandCondition(condition.coin)) },
            )
        }
    }
}

// ---------------------------------------------------------------------------
// Items tab
// ---------------------------------------------------------------------------

@Composable
private fun ItemsTab(
    items: List<CharacterItemDisplay>,
    emptyMessage: String,
    onEvent: (CharacterDetailEvent) -> Unit,
) {
    val typography = VortexTypography()
    if (items.isEmpty()) {
        Text(
            text = emptyMessage,
            style = typography.bodyMedium,
            color = secondaryTextColor,
            modifier = Modifier.padding(16.dp),
        )
        return
    }
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .padding(horizontal = 16.dp),
        verticalArrangement = Arrangement.spacedBy(8.dp),
    ) {
        items.forEach { item ->
            ExpandableEntryRow(
                name = item.name,
                expiry = item.expiry,
                expiryLabel = item.expiryLabel,
                noExpiry = item.noExpiry,
                badge = "ITIN ${item.itin}",
                isExpanded = item.isExpanded,
                isLoadingDetail = item.isLoadingDetail,
                description = item.description,
                playerText = item.playerText,
                manaAmount = item.manaAmount,
                manatypeName = item.manatypeName,
                onToggle = { onEvent(CharacterDetailEvent.ExpandItem(item.itin)) },
                onRecharge = { onEvent(CharacterDetailEvent.RechargeItem(item.itin)) },
            )
        }
    }
}

// ---------------------------------------------------------------------------
// Powers tab
// ---------------------------------------------------------------------------

@Composable
private fun PowersTab(
    powers: List<CharacterPowerDisplay>,
    runeImbues: List<CharacterImbueDisplay>,
    glyphImbues: List<CharacterImbueDisplay>,
    powersHeader: String,
    runeImbuesHeader: String,
    glyphImbuesHeader: String,
    emptyMessage: String,
    onEvent: (CharacterDetailEvent) -> Unit,
) {
    val typography = VortexTypography()
    val allEmpty = powers.isEmpty() && runeImbues.isEmpty() && glyphImbues.isEmpty()
    if (allEmpty) {
        Text(
            text = emptyMessage,
            style = typography.bodyMedium,
            color = secondaryTextColor,
            modifier = Modifier.padding(16.dp),
        )
        return
    }
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .padding(horizontal = 16.dp),
        verticalArrangement = Arrangement.spacedBy(8.dp),
    ) {
        if (powers.isNotEmpty()) {
            SectionHeader(powersHeader)
            powers.forEach { power ->
                ExpandableEntryRow(
                    name = power.name,
                    expiry = power.expiry,
                    expiryLabel = power.expiryLabel,
                    noExpiry = power.noExpiry,
                    isExpanded = power.isExpanded,
                    isLoadingDetail = power.isLoadingDetail,
                    playerText = power.playerText,
                    manaAmount = power.manaAmount,
                    manatypeName = power.manatypeName,
                    onToggle = { onEvent(CharacterDetailEvent.ExpandPower(power.poin)) },
                )
            }
        }
        if (runeImbues.isNotEmpty()) {
            Spacer(Modifier.height(4.dp))
            SectionHeader(runeImbuesHeader)
            runeImbues.forEach { rune ->
                SimpleEntryRow(
                    name = rune.name ?: "-",
                    expiry = rune.expiry,
                    expiryLabel = rune.expiryLabel,
                    noExpiry = rune.noExpiry,
                )
            }
        }
        if (glyphImbues.isNotEmpty()) {
            Spacer(Modifier.height(4.dp))
            SectionHeader(glyphImbuesHeader)
            glyphImbues.forEach { glyph ->
                SimpleEntryRow(
                    name = glyph.name ?: "-",
                    expiry = glyph.expiry,
                    expiryLabel = glyph.expiryLabel,
                    noExpiry = glyph.noExpiry,
                )
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Expandable entry row (conditions, items, powers)
// ---------------------------------------------------------------------------

@Composable
private fun ExpandableEntryRow(
    name: String,
    expiry: String?,
    expiryLabel: String,
    noExpiry: String,
    badge: String? = null,
    isExpanded: Boolean = false,
    isLoadingDetail: Boolean = false,
    description: String? = null,
    playerText: String? = null,
    manaAmount: Int? = null,
    manatypeName: String? = null,
    onToggle: () -> Unit,
    onRecharge: (() -> Unit)? = null,
) {
    val typography = VortexTypography()
    val a11y = LocalStrings.current.a11y
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .background(Color(0xFFF8F8F8), RoundedCornerShape(6.dp))
            .semantics {
                role = Role.Button
                stateDescription = if (isExpanded) a11y.expanded else a11y.collapsed
            }
            .clickable(onClick = onToggle),
    ) {
        // Header row
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 10.dp, vertical = 10.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.SpaceBetween,
        ) {
            Column(modifier = Modifier.weight(1f)) {
                Text(
                    text = name,
                    style = typography.bodyMedium,
                    fontWeight = FontWeight.Medium,
                )
                val expiryText = if (expiry != null) "$expiryLabel: $expiry" else noExpiry
                Text(
                    text = expiryText,
                    style = typography.bodySmall,
                    color = secondaryTextColor,
                )
            }
            Row(
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(8.dp),
            ) {
                if (badge != null) {
                    Text(
                        text = badge,
                        style = typography.bodySmall,
                        color = secondaryTextColor,
                    )
                }
                if (isLoadingDetail) {
                    CircularProgressIndicator(
                        modifier = Modifier.size(16.dp),
                        strokeWidth = 2.dp,
                        color = vortexRed,
                    )
                } else {
                    Text(
                        text = if (isExpanded) "▲" else "▼",
                        style = typography.bodySmall,
                        color = vortexRed,
                    )
                }
            }
        }

        // Expanded detail
        AnimatedVisibility(
            visible = isExpanded && !isLoadingDetail,
            enter = expandVertically(),
            exit = shrinkVertically(),
        ) {
            val hasContent = description != null || playerText != null ||
                (manaAmount != null && manatypeName != null)
            if (hasContent) {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(start = 10.dp, end = 10.dp, bottom = 10.dp),
                    verticalArrangement = Arrangement.spacedBy(6.dp),
                ) {
                    Divider(color = dividerColor)
                    Spacer(Modifier.height(2.dp))
                    if (manaAmount != null && manatypeName != null) {
                        Row(horizontalArrangement = Arrangement.spacedBy(4.dp)) {
                            Text(
                                text = "⚡",
                                style = typography.bodySmall,
                                color = vortexRed,
                            )
                            Text(
                                text = "$manatypeName: $manaAmount",
                                style = typography.bodySmall,
                                color = Color(0xFF222222),
                                fontWeight = FontWeight.Medium,
                            )
                        }
                    }
                    if (description != null) {
                        Text(
                            text = description,
                            style = typography.bodySmall,
                            color = Color(0xFF444444),
                            fontWeight = FontWeight.Medium,
                        )
                    }
                    if (playerText != null) {
                        Text(
                            text = playerText,
                            style = typography.bodySmall,
                            color = Color(0xFF222222),
                        )
                    }
                    if (onRecharge != null) {
                        Spacer(Modifier.height(4.dp))
                        Button(
                            onClick = onRecharge,
                            colors = ButtonDefaults.buttonColors(backgroundColor = vortexRed),
                            shape = RoundedCornerShape(6.dp),
                        ) {
                            Text(
                                text = "Recharge",
                                style = typography.bodySmall,
                                color = Color.White,
                            )
                        }
                    }
                }
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Simple (non-expandable) row for rune/glyph imbues
// ---------------------------------------------------------------------------

@Composable
private fun SimpleEntryRow(
    name: String,
    expiry: String?,
    expiryLabel: String,
    noExpiry: String,
    badge: String? = null,
) {
    val typography = VortexTypography()
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .background(Color(0xFFF8F8F8), RoundedCornerShape(6.dp))
            .padding(10.dp),
    ) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceBetween,
        ) {
            Text(
                text = name,
                style = typography.bodyMedium,
                modifier = Modifier.weight(1f),
            )
            if (badge != null) {
                Text(
                    text = badge,
                    style = typography.bodySmall,
                    color = secondaryTextColor,
                )
            }
        }
        val expiryText = if (expiry != null) "$expiryLabel: $expiry" else noExpiry
        Text(
            text = expiryText,
            style = typography.bodySmall,
            color = secondaryTextColor,
        )
    }
}

// ---------------------------------------------------------------------------
// Section header
// ---------------------------------------------------------------------------

@Composable
private fun SectionHeader(title: String) {
    val typography = VortexTypography()
    Text(
        text = title,
        style = typography.bodyLarge,
        fontWeight = FontWeight.Bold,
        color = vortexRed,
        modifier = Modifier.padding(vertical = 4.dp),
    )
}
