package com.coding.va.selfhelp.domain.model

import kotlinx.serialization.Serializable

@Serializable
data class SuccessData(
    val cardDisplay: VortexItemCardDisplay,
    val entryData: SheetEntryData,
    /** When false, the card is not printed on desktop (e.g. Mundane Items have no physical card). */
    val shouldPrintCard: Boolean = true,
    val resourcesText: String? = null,
    val notes: String? = null,
)
