import androidx.compose.ui.semantics.stateDescription
import androidx.compose.ui.unit.dp
import com.coding.va.selfhelp.i18n.LocalStrings
import com.coding.va.selfhelp.presentation.components.selectablefield.model.SelectableFieldContent
import com.coding.va.selfhelp.presentation.components.selectablefield.model.SelectableFieldDisplay
import com.coding.va.selfhelp.theme.vortexRed
import com.composeunstyled.UnstyledDropdownMenu
import com.composeunstyled.UnstyledDropdownMenuPanel


@Composable
fun SelectableField(
    display: SelectableFieldDisplay,
    value: String? = null,
    isError: Boolean = false,
    errorText: String? = null,
    modifier: Modifier = Modifier,
    onSelected: (SelectableFieldContent) -> Unit = {}
) {
    var expanded by remember { mutableStateOf(false) }
    val a11y = LocalStrings.current.a11y

    Column(modifier = modifier) {
        Box(modifier = Modifier.fillMaxWidth()) {
            UnstyledDropdownMenu(onExpandRequest = { expanded = true }) {
                Box(Modifier.fillMaxWidth()) {
                    Box(
                        modifier = Modifier
                            .padding(top = 8.dp)
                            .fillMaxWidth()
                            .semantics(mergeDescendants = true) {
                                role = Role.DropdownList
                                stateDescription = if (expanded) a11y.dropdownExpanded
                                else a11y.dropdownCollapsed
                                if (isError && errorText != null) error(errorText)
                            }
                            .minimumInteractiveComponentSize()
                            .clickable { expanded = !expanded }
                    ) {
                        Text(
                            modifier = Modifier
                                .fillMaxWidth()
                                .border(
                                    1.dp,
                                    if (isError) MaterialTheme.colors.error.copy(alpha = ContentAlpha.disabled)
                                    else MaterialTheme.colors.onSurface.copy(alpha = ContentAlpha.disabled),
                                    RoundedCornerShape(4.dp)
                                )
                                .padding(16.dp),
                            text = value ?: display.label
                        )
                    }
                }

                UnstyledDropdownMenuPanel(
                    expanded = expanded,
                    onDismissRequest = { expanded = false },
                    modifier = Modifier.padding(vertical = 4.dp)
                        .width(240.dp)
                        .shadow(4.dp, RoundedCornerShape(8.dp))
                        .clip(RoundedCornerShape(8.dp))
                        .background(Color.White),
                    enter = scaleIn(
                        animationSpec = tween(durationMillis = 120, easing = LinearOutSlowInEasing),
                        initialScale = 0.8f,
                        transformOrigin = TransformOrigin(0f, 0f)
                    ) + fadeIn(tween(durationMillis = 30)),
                    exit = scaleOut(
                        animationSpec = tween(durationMillis = 1, delayMillis = 75),
                        targetScale = 1f
                    ) + fadeOut(tween(durationMillis = 75))
                ) {
                    Column(modifier = Modifier.verticalScroll(rememberScrollState())) {
                        display.content.forEach { content ->
                            Box(
                                modifier = Modifier
                                    .padding(4.dp)
                                    .clip(RoundedCornerShape(8.dp))
                                    .semantics { role = Role.Button }
                                    .minimumInteractiveComponentSize()
                                    .clickable { onSelected(content); expanded = false }
                            ) {
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    modifier = Modifier.padding(horizontal = 8.dp, vertical = 2.dp)
                                ) {
                                    Text(
                                        text = content.displayValue,
                                        modifier = Modifier.fillMaxWidth()
                                            .padding(vertical = 8.dp, horizontal = 4.dp)
                                    )
                                }
                            }
                        }
                    }
                }
            }
        }

        if (isError && errorText != null) {
            Text(
                text = errorText,
                color = vortexRed,
                modifier = Modifier
                    .padding(start = 16.dp, top = 4.dp)
                    .semantics { liveRegion = LiveRegionMode.Polite },
                style = MaterialTheme.typography.caption,
            )
        }
    }
}
