    fun getAllImbueTypes(isPerson: Boolean, strings: AppStrings): List<ImbueType> {
        return listOf(
            extraEnergy(strings),
            spells(strings),
            resistances(strings),
            immunities(strings),
            protection(strings),
            skill(strings),
            weaponSkill(strings),
            reduceDamage(strings),
            reduceDamagePermanent(strings),
            teacher(strings),
            custom(strings),
        ).filter {
            if (isPerson) {
                it.canBePersonal
            } else true
        }
    }
