package com.coding.va.selfhelp.data.models

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable

// ---------------------------------------------------------------------------
// Character list response — GET /characters/{plin}
// ---------------------------------------------------------------------------

@Serializable
data class CharacterListResponse(
    val list: List<CharacterSummaryEntity> = emptyList(),
)

@Serializable
data class CharacterSummaryEntity(
    val plin: Int,
    val chin: Int,
    val name: String,
    val status: String,
)

// ---------------------------------------------------------------------------
// Character detail response — GET /characters/{plin}/{chin}
// ---------------------------------------------------------------------------

@Serializable
data class CharacterDetailEntity(
    val plin: Int,
    val chin: Int,
    val name: String,
    val xp: String? = null,
    val belief: String? = null,
    val group: String? = null,
    val world: String? = null,
    val status: String,
    val faction: String? = null,
    @SerialName("referee_notes") val refereeNotes: String? = null,
    val notes: String? = null,
    val items: CharacterSubListEntity<CharacterItemEntity> = CharacterSubListEntity(),
    val conditions: CharacterSubListEntity<CharacterConditionEntity> = CharacterSubListEntity(),
    val powers: CharacterSubListEntity<CharacterPowerEntity> = CharacterSubListEntity(),
    val skills: CharacterSubListEntity<CharacterSkillEntity> = CharacterSubListEntity(),
    val runeimbues: CharacterSubListEntity<CharacterRuneImbueEntity> = CharacterSubListEntity(),
    val glyphimbues: CharacterSubListEntity<CharacterGlyphImbueEntity> = CharacterSubListEntity(),
)

@Serializable
data class CharacterSubListEntity<T>(
    val list: List<T> = emptyList(),
)

// ---------------------------------------------------------------------------
// Sub-entities
// ---------------------------------------------------------------------------

@Serializable
data class CharacterItemEntity(
    val itin: Int,
    val name: String,
    val expiry: String? = null,
    val deprecated: Boolean = false,
)

@Serializable
data class CharacterConditionEntity(
    val expiry: String? = null,
    val condition: ConditionRefEntity,
)

@Serializable
data class ConditionRefEntity(
    val coin: Int,
    val name: String,
    val deprecated: Boolean = false,
)

@Serializable
data class CharacterPowerEntity(
    val expiry: String? = null,
    val power: PowerRefEntity,
)

@Serializable
data class PowerRefEntity(
    val poin: Int,
    val name: String,
    val deprecated: Boolean = false,
)

@Serializable
data class CharacterSkillEntity(
    val times: Int = 1,
    val skill: SkillRefEntity,
)

@Serializable
data class SkillRefEntity(
    val id: Int,
    val name: String,
    val cost: Int = 0,
    @SerialName("times_max") val timesMax: Int = 1,
    @SerialName("mana_amount") val manaAmount: Int? = null,
    val manatype: ManatypeRefEntity? = null,
    val loresheet: Boolean = false,
    val deprecated: Boolean = false,
)

@Serializable
data class ManatypeRefEntity(
    val id: Int,
    val name: String,
    val deprecated: Boolean = false,
)

@Serializable
data class CharacterRuneImbueEntity(
    val expiry: String? = null,
    val name: String? = null,
)

@Serializable
data class CharacterGlyphImbueEntity(
    val expiry: String? = null,
    val name: String? = null,
)

// ---------------------------------------------------------------------------
// Detail responses for individual entities (fetched on demand)
// ---------------------------------------------------------------------------

/** GET /conditions/{coin} */
@Serializable
data class ConditionDetailEntity(
    val coin: Int,
    val name: String,
    @SerialName("player_text") val playerText: String? = null,
    @SerialName("mana_amount") val manaAmount: Int? = null,
    val manatype: ManatypeRefEntity? = null,
    val deprecated: Boolean = false,
)

/** GET /powers/{poin} */
@Serializable
data class PowerDetailEntity(
    val poin: Int,
    val name: String,
    @SerialName("player_text") val playerText: String? = null,
    @SerialName("mana_amount") val manaAmount: Int? = null,
    val manatype: ManatypeRefEntity? = null,
    val deprecated: Boolean = false,
)

/** GET /items/{itin} */
@Serializable
data class ItemDetailEntity(
    val itin: Int,
    val name: String,
    val description: String? = null,
    @SerialName("player_text") val playerText: String? = null,
    @SerialName("mana_amount") val manaAmount: Int? = null,
    val manatype: ManatypeRefEntity? = null,
    @SerialName("imbue_capacity") val imbueCapacity: Int? = null,
    val plin: Int? = null,
    val chin: Int? = null,
    val character: ItemOwnerCharacterEntity? = null,
    val expiry: String? = null,
    val deprecated: Boolean = false,
)
@Serializable
data class ItemOwnerCharacterEntity(
    val plin: Int,
    val chin: Int,
    val name: String,
    val status: String,
)
