package com.coding.va.selfhelp

import androidx.compose.foundation.background
import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.safeDrawingPadding
import androidx.compose.material.MaterialTheme
import androidx.compose.runtime.Composable
import androidx.compose.runtime.collectAsState
import androidx.compose.runtime.getValue
import androidx.compose.ui.Modifier
import androidx.navigation.NavController
import com.coding.va.selfhelp.i18n.LanguageRepository
import com.coding.va.selfhelp.i18n.LocalStrings
import com.coding.va.selfhelp.presentation.a11y.LocalReduceMotion
import com.coding.va.selfhelp.presentation.a11y.rememberReduceMotion
import com.coding.va.selfhelp.presentation.screens.mainscreen.MainScreen
import com.coding.va.selfhelp.presentation.screens.mainscreen.MainViewModel
import com.coding.va.selfhelp.theme.borderColor
import androidx.compose.runtime.CompositionLocalProvider
import org.koin.compose.koinInject

@Composable
fun App(mainViewModel: MainViewModel, onNavHostReady: suspend (NavController) -> Unit = {}) {
    val languageRepository: LanguageRepository = koinInject()
    val strings by languageRepository.stringsFlow().collectAsState()
    val reduceMotion by rememberReduceMotion()

    MaterialTheme {
        CompositionLocalProvider(
            LocalStrings provides strings,
            LocalReduceMotion provides reduceMotion,
        ) {
            // Fill the entire screen (including behind system bars) with borderColor, then pad the
            // content so it stays in the safe drawing area (above nav bar, below status bar, etc.).
            // safeDrawingPadding() is a no-op on desktop / iOS / web so this is safe in commonMain.
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .background(borderColor)
                    .safeDrawingPadding()
            ) {
                MainScreen(mainViewModel, onNavHostReady)
            }
        }
    }
}
