package com.coding.va.selfhelp.data.di

import co.touchlab.kermit.Logger as KermitLogger
import com.coding.va.selfhelp.di.DatabaseDriverFactory
import com.coding.va.selfhelp.di.currentVoidEnvironment
import com.coding.va.selfhelp.domain.constants.Constants
import com.coding.va.selfhelp.domain.session.SessionManager
import com.russhwolf.settings.Settings
import io.ktor.client.HttpClient
import io.ktor.client.plugins.HttpRequestRetry
import io.ktor.client.plugins.HttpResponseValidator
import io.ktor.client.plugins.HttpTimeout
import io.ktor.client.plugins.contentnegotiation.ContentNegotiation
import io.ktor.client.plugins.defaultRequest
import io.ktor.client.plugins.logging.LogLevel
import io.ktor.client.plugins.logging.Logger
import io.ktor.client.plugins.logging.Logging
import io.ktor.http.ContentType
import io.ktor.http.HttpStatusCode
import io.ktor.http.contentType
import io.ktor.serialization.kotlinx.json.json
import kotlinx.serialization.ExperimentalSerializationApi
import kotlinx.serialization.json.Json
import org.koin.core.annotation.ComponentScan
import org.koin.core.annotation.Module
import org.koin.core.annotation.Named
import org.koin.core.annotation.Single

const val VOID_CLIENT = "voidHttpClient"
const val SHEETS_CLIENT = "sheetsHttpClient"

@Module
@ComponentScan("com.coding.va.selfhelp.data")
class DataModule {

    @Single
    fun databaseDriverFactory(): DatabaseDriverFactory = DatabaseDriverFactory()

    @OptIn(ExperimentalSerializationApi::class)
    @Single
    @Named(VOID_CLIENT)
    fun voidHttpClient(
        sessionManager: SessionManager,
    ): HttpClient = HttpClient {
        install(HttpTimeout) {
            socketTimeoutMillis = 30_000
            requestTimeoutMillis = 30_000
        }
        install(Logging) {
            level = LogLevel.HEADERS
            logger = object : Logger {
                override fun log(message: String) {
                    KermitLogger.d(tag = "VoidApiClient", null) { message }
                }
            }
        }
        install(HttpRequestRetry) {
            maxRetries = 2
            retryIf { _, response ->
                response.status == HttpStatusCode.Unauthorized
            }
            delayMillis { 500L }
        }
        HttpResponseValidator {
            val settings = Settings()
            validateResponse { response ->
                if (response.status == HttpStatusCode.Unauthorized) {
                    val hadToken = settings.getStringOrNull(Constants.SETTINGS_KEY_JWT)?.isNotBlank() == true
                    if (hadToken) {
                        KermitLogger.withTag("VoidApiClient").w { "Session expired — 3 consecutive 401s, clearing JWT" }
                        settings.remove(Constants.SETTINGS_KEY_JWT)
                        sessionManager.notifySessionExpired()
                    }
                }
            }
        }
        defaultRequest {
            url(currentVoidEnvironment.baseUrl)
            contentType(ContentType.Application.Json)
        }
        install(ContentNegotiation) {
            json(Json {
                prettyPrint = true
                isLenient = true
                ignoreUnknownKeys = true
                explicitNulls = false
            })
        }
    }

    @OptIn(ExperimentalSerializationApi::class)
    @Single
    @Named(SHEETS_CLIENT)
    fun sheetsHttpClient(): HttpClient = HttpClient {
        install(HttpTimeout) {
            socketTimeoutMillis = 60_000
            requestTimeoutMillis = 60_000
        }
        install(Logging) {
            level = LogLevel.ALL
            logger = object : Logger {
                override fun log(message: String) {
                    co.touchlab.kermit.Logger.d(tag = "KtorClient", null) { message }
                }
            }
        }
        install(HttpRequestRetry) {
            maxRetries = 2
            retryIf { _, response ->
                response.status.value == 503
            }
            delayMillis { 1000L }
        }
        defaultRequest {
            url("https://sheets.googleapis.com")
        }
        install(ContentNegotiation) {
            json(Json {
                prettyPrint = true
                isLenient = true
                ignoreUnknownKeys = true
                explicitNulls = false
            })
        }
    }
}
