package com.coding.va.selfhelp.presentation.screens.success

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.coding.va.selfhelp.di.getPlatform
import com.coding.va.selfhelp.domain.use_cases.PrintingUseCase
import com.coding.va.selfhelp.domain.use_cases.SavedCreationUseCase
import com.coding.va.selfhelp.domain.use_cases.SetPrinted
import com.coding.va.selfhelp.i18n.AppStrings
import com.coding.va.selfhelp.i18n.localizedName
import com.coding.va.selfhelp.presentation.methods.SavedCreation
import com.coding.va.selfhelp.presentation.screens.mainscreen.actions.MainActions
import com.coding.va.selfhelp.presentation.screens.model.getEasyName
import com.coding.va.selfhelp.presentation.screens.success.model.SuccessData
import com.coding.va.selfhelp.presentation.screens.success.model.SuccessDisplay
import com.coding.va.selfhelp.presentation.screens.success.model.SuccessEvent
import com.coding.va.selfhelp.utils.TYPE
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import org.koin.android.annotation.KoinViewModel

@KoinViewModel
class SuccessViewModel(
    private val printing: PrintingUseCase,
    private val setPrinted: SetPrinted,
    private val savedCreationUseCase: SavedCreationUseCase,
    private val strings: AppStrings,
) : ViewModel() {

    companion object {
        const val DELAY = 120000L // 2 minutes
        private const val PRINT_TIMEOUT = 30_000L
    }

    private val _display = MutableStateFlow(SuccessDisplayMapper.provideLoading(strings))
    val display = _display.asStateFlow()

    private var mainActions: MainActions? = null
    private var data: SuccessData? = null
    private var isInitialized = false
    private var didPrint = false

    fun initVM(data: SuccessData, mainActions: MainActions) {
        this.mainActions = mainActions
        this.data = data
        if (!isInitialized) {
            isInitialized = true
            viewModelScope.launch {
                if (getPlatform() == TYPE.DESKTOP) {
                    _display.emit(SuccessDisplayMapper.mapPrinting(data, strings))
                    // Safety net: if still loading after timeout, show failure
                    launch {
                        delay(PRINT_TIMEOUT)
                        if (_display.value is SuccessDisplay.Loading) {
                            _display.emit(SuccessDisplayMapper.provideFailure(strings))
                        }
                    }
                } else {
                    savedCreationUseCase.set(SavedCreation(data.entryData.getCardCode, data.entryData.type.localizedName(strings), data.cardDisplay.getEasyName(data.entryData.type), vortexCard = data.cardDisplay, resourcesText = data.resourcesText, notes = data.notes)).onFailure {
                        println("Error saving creation: $it")
                    }.getOrNull()
                    _display.emit(SuccessDisplayMapper.mapSuccess(data, strings))
                }
            }
        }
    }

    fun onEvent(event: SuccessEvent) {
        viewModelScope.launch {
            when (event) {
                is SuccessEvent.PrintCard -> {
                    println("PrintCard event received, didPrint=$didPrint")
                    if (!didPrint) {
                        printing.printImage(event.card).onSuccess {
                            didPrint = true
                            _display.emit(SuccessDisplayMapper.mapSuccess(data, strings))
                            data?.entryData?.let {
                                setPrinted(it).getOrNull()
                            }
                        }.onFailure {
                            _display.emit(SuccessDisplayMapper.provideFailure(strings))
                        }
                    } else {
                        _display.emit(SuccessDisplayMapper.mapSuccess(data, strings))
                    }
                }

                is SuccessEvent.Close -> {
                    mainActions?.home()
                }

                is SuccessEvent.Retry -> {
                    _display.emit(SuccessDisplayMapper.mapPrinting(data, strings))
                }
            }
        }
    }
}
