package com.coding.va.selfhelp.domain.model

data class MundaneInspirationSupplier(
    val amount: String = "",
    val plin: Pair<String, String> = Pair("", ""),
)

data class MundaneForm(
    val selectedSkill: MundaneSkill? = null,
    /** Only shown/used when selectedSkill?.hasQuantity == true */
    val quantity: String = "1",
    val crafterPlin: Pair<String, String> = Pair("", ""),
    /** Inspiration suppliers — optional, leave empty when materials are used instead */
    val inspirationSuppliers: Map<Int, MundaneInspirationSupplier> = mapOf(1 to MundaneInspirationSupplier()),
    /** Target plin for SKILL_RESEARCH_BOOK, BOOK_OF_EXPERIENCES, MARRIAGE_JEWELRY (player 1) */
    val targetPlin: Pair<String, String> = Pair("", ""),
    /** Second target plin, only used for MARRIAGE_JEWELRY (player 2) */
    val targetPlin2: Pair<String, String> = Pair("", ""),
    val notes: String = "",
)
