package com.coding.va.selfhelp.presentation.screens.login

import com.coding.va.selfhelp.domain.model.SocialProvider
import com.coding.va.selfhelp.i18n.AppStrings
import com.coding.va.selfhelp.presentation.screens.login.model.LoginScreenDisplay
import com.coding.va.selfhelp.presentation.screens.login.model.SocialProviderDisplay

object LoginDisplayProvider {

    fun loading() = LoginScreenDisplay.Loading

    /** Provider names handled natively or not supported — excluded from the web OAuth list. */
    private val EXCLUDED_PROVIDERS = setOf("google", "gitlab", "apple")

    fun display(strings: AppStrings, providers: List<SocialProvider>) = LoginScreenDisplay.Display(
        title = strings.login.sectionTitle,
        providers = providers
            .filter { it.name.lowercase() !in EXCLUDED_PROVIDERS }
            .map { it.toDisplay(strings) },
        googleButtonLabel = strings.login.googleButton,
        appleButtonLabel = strings.login.appleButton,
        isAuthenticating = false,
        backButton = strings.login.backButton,
    )

    fun authenticating(current: LoginScreenDisplay.Display) =
        current.copy(isAuthenticating = true)

    fun unlinkedAccount(strings: AppStrings) = LoginScreenDisplay.Error(
        title = strings.login.loginUnlinkedTitle,
        description = strings.login.loginUnlinkedDescription,
        retryButton = strings.login.backButton,
        backButton = strings.login.backButton,
    )

    fun error(strings: AppStrings) = LoginScreenDisplay.Error(
        title = strings.login.loginErrorTitle,
        description = strings.login.loginErrorDescription,
        retryButton = strings.login.loginErrorButton,
        backButton = strings.login.backButton,
    )

    fun loggedIn(strings: AppStrings, jwt: String) = LoginScreenDisplay.LoggedIn(
        title = strings.login.sectionTitle,
        label = strings.login.loggedInPrefix + jwt.take(12) + "…",
        backButton = strings.login.backButton,
    )

    private fun SocialProvider.toDisplay(strings: AppStrings) = SocialProviderDisplay(
        name = name,
        buttonLabel = when (name.lowercase()) {
            "discord" -> strings.login.discordButton
            else -> "Login with ${name.replaceFirstChar { it.uppercase() }}"
        }
    )
}
