import com.coding.va.selfhelp.theme.secondaryTextColor
import com.coding.va.selfhelp.theme.successGreen
import com.coding.va.selfhelp.theme.tertiaryTextColor

@Composable
fun CharacterSelectContent(
    display: CharacterSelectScreenDisplay.Display,
    onEvent: (CharacterSelectEvent) -> Unit,
) {
    val typography = VortexTypography()
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .padding(horizontal = 16.dp, vertical = 8.dp),
        verticalArrangement = Arrangement.spacedBy(12.dp),
    ) {
        Text(
            text = display.subtitle,
            style = typography.bodyMedium,
            color = secondaryTextColor,
            modifier = Modifier.padding(vertical = 4.dp),
        )

        display.characters.forEach { character ->
            CharacterCard(character = character, onSelect = {
                onEvent(CharacterSelectEvent.SelectCharacter(character.plin, character.chin))
            })
        }
    }
}

@Composable
private fun CharacterCard(
    character: CharacterSelectItemDisplay,
    onSelect: () -> Unit,
) {
    val typography = VortexTypography()
    val composedLabel = "${character.name}, CHIN ${character.chin}, ${character.statusLabel}"
    Card(
        modifier = Modifier
            .fillMaxWidth()
            .semantics(mergeDescendants = true) {
                role = Role.Button
                contentDescription = composedLabel
            }
            .clickable(onClick = onSelect),
        elevation = 2.dp,
        shape = RoundedCornerShape(8.dp),
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(16.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.SpaceBetween,
        ) {
            Column(modifier = Modifier.weight(1f)) {
                Text(
                    text = character.name,
                    style = typography.bodyLarge,
                    fontWeight = FontWeight.Bold,
                )
                Text(
                    text = "CHIN ${character.chin}",
                    style = typography.bodySmall,
                    color = secondaryTextColor,
                )
            }
            StatusBadge(status = character.statusLabel)
        }
    }
}

@Composable
private fun StatusBadge(status: String) {
    val isActive = status.lowercase() == "active"
    val bgColor = if (isActive) successGreen else tertiaryTextColor
    // Icon glyph is a second, non-color channel so users who can't see color
    // (WCAG 1.4.1) still read the status at a glance.
    val glyph = if (isActive) "● " else "○ "
    Box(
        modifier = Modifier
            .background(bgColor, RoundedCornerShape(4.dp))
            .padding(horizontal = 8.dp, vertical = 4.dp),
    ) {
        Text(
            text = glyph + status,
            color = Color.White,
            fontSize = 12.sp,
            fontWeight = FontWeight.Medium,
        )
    }
}
