package com.coding.va.selfhelp.domain.model

enum class EnergyType(val backendName: String) {
    ELEMENTAL_MANA("Elemental"),
    SPIRITUAL_MANA("Spiritual"),
    ELEMENTAL_RITUAL("Elemental Ritual"),
    SPIRITUAL_RITUAL("Spiritual Ritual"),
    WILLPOWER("Willpower"),
    INSPIRATION("Inspiration"),
    ;

    companion object {
        fun fromBackendName(name: String): EnergyType? =
            entries.firstOrNull { it.backendName.equals(name, ignoreCase = true) }
    }
}
