package com.coding.va.selfhelp.data

import com.coding.va.selfhelp.BuildKonfig

/**
 * Public facade for [BuildKonfig] values that are needed outside the data module.
 * [BuildKonfig] is generated as `internal`, so this object bridges it to dependent modules.
 */
object AppConfig {
    val isDebug: Boolean get() = BuildKonfig.isDebug
    val GEMINI_API_KEY: String get() = BuildKonfig.GEMINI_API_KEY
    val GOOGLE_ANDROID_CLIENT_ID: String get() = BuildKonfig.GOOGLE_ANDROID_CLIENT_ID
    val GOOGLE_WEB_CLIENT_ID: String get() = BuildKonfig.GOOGLE_WEB_CLIENT_ID
    val GOOGLE_IOS_CLIENT_ID: String get() = BuildKonfig.GOOGLE_IOS_CLIENT_ID
    val FIREBASE_PROJECT_ID: String get() = BuildKonfig.FIREBASE_PROJECT_ID
    val FIREBASE_APPLICATION_ID: String get() = BuildKonfig.FIREBASE_APPLICATION_ID
    val FIREBASE_API_KEY: String get() = BuildKonfig.FIREBASE_API_KEY
    val SHEETS_KEY: String get() = BuildKonfig.SHEETS_KEY
    val SHEETS_EMAIL: String get() = BuildKonfig.SHEETS_EMAIL
}
