import com.coding.va.selfhelp.presentation.commoninterface.onCreate
import com.coding.va.selfhelp.presentation.components.Button
import com.coding.va.selfhelp.presentation.screens.history.model.HistoryEvent
import com.coding.va.selfhelp.presentation.screens.history.model.HistoryScreenDisplay
import com.coding.va.selfhelp.presentation.screens.mainscreen.actions.MainActions
import com.coding.va.selfhelp.theme.VortexTypography

@Composable
fun HistoryScreen(
    viewModel: HistoryViewModel,
    mainActions: MainActions,
) {
    val display by viewModel.display.collectAsState()
    val typography = VortexTypography()

    val density = LocalDensity.current
    val windowInfo = LocalWindowInfo.current
    val screenHeight = with(density) {
        val statusBar = WindowInsets.statusBars.getTop(density)
        val navBar = WindowInsets.navigationBars.getBottom(density)
        (windowInfo.containerSize.height - statusBar - navBar).toDp()
    }

    // Consume all leftover scroll so the outer NavHost verticalScroll never activates
    val consumeAllScroll = remember {
        object : NestedScrollConnection {
            override fun onPostScroll(
                consumed: Offset,
                available: Offset,
                source: NestedScrollSource,
            ): Offset = available
        }
    }

    LocalLifecycleOwner.current.onCreate {
        viewModel.initVM(mainActions)
    }

    when (val state = display) {
        is HistoryScreenDisplay.Loading -> {
            Box(
                modifier = Modifier
                    .requiredHeight(screenHeight)
                    .fillMaxWidth()
                    .nestedScroll(consumeAllScroll),
                contentAlignment = Alignment.Center,
            ) {
                CircularProgressIndicator()
            }
        }

        is HistoryScreenDisplay.Error -> {
            Box(
                modifier = Modifier
                    .requiredHeight(screenHeight)
                    .fillMaxWidth()
                    .padding(24.dp)
                    .nestedScroll(consumeAllScroll),
                contentAlignment = Alignment.Center,
            ) {
                Text(text = state.message, style = typography.bodyMedium)
            }
        }

        is HistoryScreenDisplay.Display -> {
            Box(
                modifier = Modifier
                    .requiredHeight(screenHeight)
                    .fillMaxWidth()
                    .background(Color.White)
                    .nestedScroll(consumeAllScroll),
            ) {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .verticalScroll(rememberScrollState())
                        .padding(bottom = 72.dp),
                ) {
                    HistoryContent(state, viewModel::onEvent)
                }

                Button(
                    modifier = Modifier
                        .align(Alignment.BottomStart)
                        .padding(start = 16.dp, bottom = 16.dp)
                        .height(50.dp),
                    onClick = { viewModel.onEvent(HistoryEvent.Back) },
                ) {
                    Text(text = state.backButton)
                }
            }
        }
    }
}
