package com.coding.va.selfhelp.presentation.methods

import com.coding.va.selfhelp.i18n.AppStrings
import com.coding.va.selfhelp.presentation.components.errorbox.model.ErrorBoxDisplay

object ApiErrorDisplayProvider {

    fun error(error: String?, strings: AppStrings) = ErrorBoxDisplay(
        title = strings.common.apiErrorTitle,
        description = "${strings.common.apiErrorDescriptionPrefix}$error",
        acceptButton = null,
        retryButton = strings.common.apiErrorButton,
    )
}
