package com.coding.va.selfhelp.i18n

import com.russhwolf.settings.Settings
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import org.koin.core.annotation.Single

private const val KEY_LANGUAGE = "language"

/**
 * Manages the app-wide language preference.
 *
 * The selected language tag ("en" or "nl") is persisted across sessions via [Settings].
 * [stringsFlow] exposes the active [AppStrings] reactively; call [toggleLanguage] to switch
 * between English and Dutch at runtime without restarting the app.
 */
@Single
class LanguageRepository {

    private val settings = Settings()

    private val _strings = MutableStateFlow(stringsForTag(settings.getString(KEY_LANGUAGE, "en")))

    /** The current language tag ("en" or "nl"). */
    var currentTag: String = settings.getString(KEY_LANGUAGE, "en")
        private set

    /** Returns the [AppStrings] for the currently active language. */
    fun getStrings(): AppStrings = _strings.value

    /** Reactive stream of the active [AppStrings]. Collect this in App.kt. */
    fun stringsFlow(): StateFlow<AppStrings> = _strings.asStateFlow()

    /** Switches between "en" and "nl" and persists the choice. */
    fun toggleLanguage() {
        currentTag = if (currentTag == "nl") "en" else "nl"
        _strings.value = stringsForTag(currentTag)
        settings.putString(KEY_LANGUAGE, currentTag)
    }

    /**
     * The label to show on the language-toggle button.
     * It displays the language you will switch *to*, e.g. "NL" when currently in English.
     */
    fun toggleLabel(): String = if (currentTag == "nl") "EN" else "NL"

    private fun stringsForTag(tag: String): AppStrings = if (tag == "nl") NlStrings else EnStrings
}
