package com.coding.va.selfhelp.presentation.screens.history.model

import androidx.compose.ui.text.AnnotatedString
import com.coding.va.selfhelp.presentation.screens.model.VortexItemCardDisplay

sealed class HistoryScreenDisplay {
    data object Loading : HistoryScreenDisplay()

    data class Display(
        val title: String,
        val subtitle: String,
        val emptyMessage: String,
        val items: List<HistoryItemDisplay>,
        val backButton: String,
    ) : HistoryScreenDisplay()

    data class Error(val message: String) : HistoryScreenDisplay()
}

data class HistoryItemDisplay(
    val cardCode: String,
    val kindOfCreation: String,
    val name: String?,
    val plinText: String?,
    val printerCodeLabel: String,
    val vortexCard: VortexItemCardDisplay?,
    val isExpanded: Boolean = false,
    val resourcesText: String? = null,
    val notes: String? = null,
    val envelopeInstruction: AnnotatedString? = null,
    val noCardDetailsText: String,
    val canRepeat: Boolean = false,
    val repeatButtonLabel: String = "",
)

sealed class HistoryEvent {
    data class ToggleExpand(val index: Int) : HistoryEvent()
    data class RepeatCreation(val index: Int) : HistoryEvent()
    data object Back : HistoryEvent()
}
