package com.coding.va.selfhelp.presentation.screens.character.detail

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import co.touchlab.kermit.Logger
import com.coding.va.selfhelp.domain.constants.Constants
import com.coding.va.selfhelp.domain.model.CharacterDetail
import com.coding.va.selfhelp.domain.model.EnergyType
import com.coding.va.selfhelp.domain.respository.CharactersRepository
import com.coding.va.selfhelp.domain.use_cases.GetActiveCharacterUseCase
import com.coding.va.selfhelp.domain.use_cases.GetCharacterDetailUseCase
import com.coding.va.selfhelp.i18n.AppStrings
import com.russhwolf.settings.Settings
import com.coding.va.selfhelp.presentation.screens.character.detail.model.CharacterDetailEvent
import com.coding.va.selfhelp.presentation.screens.character.detail.model.CharacterDetailScreenDisplay
import com.coding.va.selfhelp.presentation.screens.character.detail.model.EnergyTotalDisplay
import com.coding.va.selfhelp.presentation.screens.mainscreen.actions.MainActions
import com.coding.va.selfhelp.presentation.screens.mainscreen.destinations.MainDestinations
import kotlinx.coroutines.async
import kotlinx.coroutines.awaitAll
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import org.koin.android.annotation.KoinViewModel

private val log = Logger.withTag("CharacterDetail")

@KoinViewModel
class CharacterDetailViewModel(
    private val getCharacterDetail: GetCharacterDetailUseCase,
    private val getActiveCharacter: GetActiveCharacterUseCase,
    private val charactersRepository: CharactersRepository,
    private val strings: AppStrings,
) : ViewModel() {

    private val settings = Settings()

    private val _display = MutableStateFlow(
        CharacterDetailDisplayProvider.loading()
    )
    val display = _display.asStateFlow()

    private var mainActions: MainActions? = null

    fun initVM(actions: MainActions) {
        mainActions = actions
        viewModelScope.launch { loadDetail() }
    }

    private suspend fun loadDetail() {
        _display.emit(CharacterDetailDisplayProvider.loading())

        val active = getActiveCharacter()
        if (active == null) {
            log.w { "CharacterDetail - no active character saved, redirecting to select" }
            mainActions?.navigate(MainDestinations.CharacterSelect)
            return
        }

        log.d { "CharacterDetail - loading plin=${active.plin} chin=${active.chin}" }
        getCharacterDetail(active.plin, active.chin)
            .onSuccess { detail ->
                log.d { "CharacterDetail - loaded: ${detail.name}" }
                _display.emit(CharacterDetailDisplayProvider.display(strings, detail))
                // Fire energy totals fetch in the background — updates display when ready
                viewModelScope.launch { loadEnergyTotals(detail) }
            }
            .onFailure { err ->
                log.e(err) { "CharacterDetail - failed: ${err.message}" }
                _display.emit(CharacterDetailDisplayProvider.error(strings))
            }
    }

    private suspend fun loadEnergyTotals(detail: CharacterDetail) {
        log.d { "CharacterDetail - computing energy totals" }
        val energyMap = mutableMapOf<String, Int>()

        // 1. Skills — already inline in the character detail
        detail.skills.forEach { skill ->
            val typeName = skill.manatypeName ?: return@forEach
            val amount = skill.manaAmount ?: return@forEach
            if (amount > 0) {
                energyMap[typeName] = (energyMap[typeName] ?: 0) + amount * skill.times
            }
        }

        // 2. Conditions, powers, and items — all fetched in parallel
        //    Results are keyed by id so we can cache them into the display (avoids re-fetch on expand)
        val conditionJobs = detail.conditions.map { c ->
            viewModelScope.async { c.coin to charactersRepository.getConditionMana(c.coin) }
        }
        val powerJobs = detail.powers.map { p ->
            viewModelScope.async { p.poin to charactersRepository.getPowerMana(p.poin) }
        }
        val itemJobs = detail.items.map { i ->
            viewModelScope.async { i.itin to charactersRepository.getItemMana(i.itin) }
        }
        val conditionResults = conditionJobs.awaitAll()
        val powerResults = powerJobs.awaitAll()
        val itemResults = itemJobs.awaitAll()

        // Aggregate into energy map
        (conditionResults + powerResults + itemResults).forEach { (_, result) ->
            result.getOrNull()?.let { mana ->
                val amount = mana.manaAmount
                val typeName = mana.manatypeName
                if (amount != null && amount > 0 && typeName != null) {
                    energyMap[typeName] = (energyMap[typeName] ?: 0) + amount
                }
            }
        }

        val totals = energyMap
            .map { (name, total) -> EnergyTotalDisplay(manatypeName = name, total = total) }
            .sortedByDescending { it.total }

        log.d { "CharacterDetail - energy totals: $totals" }

        // Build lookup maps so expand shows mana without re-fetching
        val conditionManaMap = conditionResults.associate { (coin, r) -> coin to r.getOrNull() }
        val powerManaMap = powerResults.associate { (poin, r) -> poin to r.getOrNull() }
        val itemManaMap = itemResults.associate { (itin, r) -> itin to r.getOrNull() }

        val current = _display.value as? CharacterDetailScreenDisplay.Display ?: return
        _display.emit(
            current.copy(
                energyTotals = totals,
                conditions = current.conditions.map { c ->
                    conditionManaMap[c.coin]?.let { mana ->
                        c.copy(manaAmount = mana.manaAmount, manatypeName = mana.manatypeName)
                    } ?: c
                },
                powers = current.powers.map { p ->
                    powerManaMap[p.poin]?.let { mana ->
                        p.copy(manaAmount = mana.manaAmount, manatypeName = mana.manatypeName)
                    } ?: p
                },
                items = current.items.map { i ->
                    itemManaMap[i.itin]?.let { mana ->
                        i.copy(manaAmount = mana.manaAmount, manatypeName = mana.manatypeName, imbueCapacity = mana.imbueCapacity)
                    } ?: i
                },
            )
        )
    }

    fun onEvent(event: CharacterDetailEvent) {
        viewModelScope.launch {
            when (event) {
                is CharacterDetailEvent.Back -> mainActions?.back()
                is CharacterDetailEvent.Retry -> loadDetail()
                is CharacterDetailEvent.SwitchCharacter -> {
                    mainActions?.navigate(MainDestinations.CharacterSelect)
                }

                is CharacterDetailEvent.Logout -> {
                    settings.remove(Constants.SETTINGS_KEY_JWT)
                    charactersRepository.clearActiveCharacter()
                    mainActions?.back()
                }

                is CharacterDetailEvent.ExpandSkill -> expandSkill(event.id)
                is CharacterDetailEvent.ExpandCondition -> expandCondition(event.coin)
                is CharacterDetailEvent.ExpandPower -> expandPower(event.poin)
                is CharacterDetailEvent.ExpandItem -> expandItem(event.itin)
                is CharacterDetailEvent.RechargeItem -> navigateToRecharge(event.itin)
            }
        }
    }

    private suspend fun expandSkill(id: Int) {
        val current = _display.value as? CharacterDetailScreenDisplay.Display ?: return
        _display.emit(current.copy(skills = current.skills.map {
            if (it.id == id) it.copy(isExpanded = !it.isExpanded) else it
        }))
    }

    private suspend fun expandCondition(coin: Int) {
        val current = _display.value as? CharacterDetailScreenDisplay.Display ?: return
        // Toggle collapse if already expanded
        val existing = current.conditions.firstOrNull { it.coin == coin }
        if (existing?.isExpanded == true) {
            _display.emit(current.copy(conditions = current.conditions.map {
                if (it.coin == coin) it.copy(isExpanded = false) else it
            }))
            return
        }
        // Set loading
        _display.emit(current.copy(conditions = current.conditions.map {
            if (it.coin == coin) it.copy(isExpanded = true, isLoadingDetail = true) else it
        }))
        // Fetch
        charactersRepository.getConditionPlayerText(coin)
            .onSuccess { text ->
                val updated = _display.value as? CharacterDetailScreenDisplay.Display ?: return
                _display.emit(updated.copy(conditions = updated.conditions.map {
                    if (it.coin == coin) it.copy(isLoadingDetail = false, playerText = text) else it
                }))
            }
            .onFailure {
                val updated = _display.value as? CharacterDetailScreenDisplay.Display ?: return
                _display.emit(updated.copy(conditions = updated.conditions.map {
                    if (it.coin == coin) it.copy(isLoadingDetail = false) else it
                }))
            }
    }

    private suspend fun expandPower(poin: Int) {
        val current = _display.value as? CharacterDetailScreenDisplay.Display ?: return
        val existing = current.powers.firstOrNull { it.poin == poin }
        if (existing?.isExpanded == true) {
            _display.emit(current.copy(powers = current.powers.map {
                if (it.poin == poin) it.copy(isExpanded = false) else it
            }))
            return
        }
        _display.emit(current.copy(powers = current.powers.map {
            if (it.poin == poin) it.copy(isExpanded = true, isLoadingDetail = true) else it
        }))
        charactersRepository.getPowerPlayerText(poin)
            .onSuccess { text ->
                val updated = _display.value as? CharacterDetailScreenDisplay.Display ?: return
                _display.emit(updated.copy(powers = updated.powers.map {
                    if (it.poin == poin) it.copy(isLoadingDetail = false, playerText = text) else it
                }))
            }
            .onFailure {
                val updated = _display.value as? CharacterDetailScreenDisplay.Display ?: return
                _display.emit(updated.copy(powers = updated.powers.map {
                    if (it.poin == poin) it.copy(isLoadingDetail = false) else it
                }))
            }
    }

    private suspend fun expandItem(itin: Int) {
        val current = _display.value as? CharacterDetailScreenDisplay.Display ?: return
        val existing = current.items.firstOrNull { it.itin == itin }
        if (existing?.isExpanded == true) {
            _display.emit(current.copy(items = current.items.map {
                if (it.itin == itin) it.copy(isExpanded = false) else it
            }))
            return
        }
        _display.emit(current.copy(items = current.items.map {
            if (it.itin == itin) it.copy(isExpanded = true, isLoadingDetail = true) else it
        }))
        charactersRepository.getItemDetails(itin)
            .onSuccess { detail ->
                val updated = _display.value as? CharacterDetailScreenDisplay.Display ?: return
                _display.emit(updated.copy(items = updated.items.map {
                    if (it.itin == itin) it.copy(
                        isLoadingDetail = false,
                        description = detail.description,
                        playerText = detail.playerText,
                    ) else it
                }))
            }
            .onFailure {
                val updated = _display.value as? CharacterDetailScreenDisplay.Display ?: return
                _display.emit(updated.copy(items = updated.items.map {
                    if (it.itin == itin) it.copy(isLoadingDetail = false) else it
                }))
            }
    }

    private fun navigateToRecharge(itin: Int) {
        val current = _display.value as? CharacterDetailScreenDisplay.Display ?: return
        val item = current.items.firstOrNull { it.itin == itin } ?: return
        val active = getActiveCharacter()
        val energyTypeName = item.manatypeName?.let { name ->
            EnergyType.fromBackendName(name)?.name
        } ?: ""
        val neededEnergy = (item.imbueCapacity ?: item.manaAmount)?.toString() ?: ""
        mainActions?.navigate(
            MainDestinations.RechargeItem(
                prefillItin = itin.toString(),
                prefillEnergyAmount = neededEnergy,
                prefillEnergyType = energyTypeName,
                prefillPlin = active?.plin?.toString() ?: "",
                prefillChin = active?.chin?.toString() ?: "",
            )
        )
    }

}
