    @OptIn(ExperimentalEncodingApi::class)
    actual suspend fun encryptRSA(data: String, privateKey: String): String {
        val key = privateKey
            .replace("-----BEGIN PRIVATE KEY-----", "")
            .replace("-----END PRIVATE KEY-----", "")
            .replace("\\s".toRegex(), "")
        val keyBytes = Base64.Default.decode(key)

        val crypto = js("window.crypto")
        val subtle = crypto.subtle

        val algorithm = js("""{
        name: "RSASSA-PKCS1-v1_5",
        hash: { name: "SHA-256" }
    }""")

        val privateKeyJs = (subtle.importKey(
            "pkcs8",
            keyBytes,
            algorithm,
            false,
            arrayOf("sign")
        ) as Promise<dynamic>).await()

        val dataBytes = data.toByteArray(Charsets.UTF_8)
        val signatureBytes = (subtle.sign(
            algorithm,
            privateKeyJs,
            dataBytes
        ) as Promise<ArrayBuffer>).await()

        val signatureUint8 = js("new Uint8Array(signatureBytes)")
        val signatureByteArray = ByteArray(signatureUint8.length) { index ->
            (signatureUint8[index] as Number).toInt().toByte()
        }

        // Encode to Base64 URL-safe
        return Base64.UrlSafe.encode(signatureByteArray).trimEnd('=')
    }

