package com.coding.va.selfhelp.domain.use_cases

import com.coding.va.selfhelp.domain.respository.AuthRepository
import org.koin.core.annotation.Factory

/**
 * Exchanges an Apple identity token (obtained from [ASAuthorizationAppleIDProvider] on iOS)
 * for an app JWT by calling the backend's `/auth/login/apple?token=` endpoint.
 *
 * The JWT is stored via [AuthRepository] on success.
 *
 * @param idToken The Apple identity token string returned by the native sign-in SDK.
 * @return The app JWT string on success.
 */
@Factory
class LoginWithAppleUseCase(private val repository: AuthRepository) {

    suspend operator fun invoke(idToken: String): Result<String> =
        repository.loginWithApple(idToken)
}
