package com.coding.va.selfhelp.domain.use_cases

import com.coding.va.selfhelp.domain.model.CharacterDetail
import com.coding.va.selfhelp.domain.respository.CharactersRepository
import org.koin.core.annotation.Factory

@Factory
class GetCharacterDetailUseCase(private val repository: CharactersRepository) {
    suspend operator fun invoke(plin: Int, chin: Int): Result<CharacterDetail> =
        repository.getCharacterDetail(plin, chin)
}
