package com.coding.va.selfhelp.di

import androidx.compose.runtime.Composable
import androidx.compose.ui.graphics.ImageBitmap
import androidx.compose.ui.graphics.toComposeImageBitmap
import androidx.compose.ui.platform.Clipboard
import com.coding.va.selfhelp.utils.TYPE
import kotlinx.browser.window
import org.jetbrains.skia.Image

actual suspend fun clipData(clipboard: Clipboard): String? {
    return window.navigator.clipboard.readText().toString().trim()
}

actual suspend fun setClipData(clipboard: Clipboard, message: String) {
    window.navigator.clipboard.writeText(message)
}

actual fun ByteArray.toComposeImageBitmap(): ImageBitmap {
    return Image.makeFromEncoded(this).toComposeImageBitmap()
}

actual fun isNetworkAvailable(): Boolean {
    return window.navigator.onLine
}

actual fun captureComposable(content: @Composable () -> Unit): ImageBitmap {
    throw UnsupportedOperationException("Not used on Web")
}

actual suspend fun signInWithGoogle(): Result<String> =
    Result.failure(UnsupportedOperationException("Native Google Sign-In is not supported on web"))

actual suspend fun signInWithApple(): Result<String> =
    Result.failure(UnsupportedOperationException("Apple Sign-In is not supported on web"))

actual val isIosPlatform: Boolean = false

actual fun sha256(input: ByteArray): ByteArray =
    throw UnsupportedOperationException("SHA-256 not available on web")

actual fun launchOAuthBrowser(url: String, callbackScheme: String) {
    // Web: open the auth URL in the same tab. The callback URL would need to be a
    // web URL rather than the va-selfhelp:// scheme; full web OAuth support is out of scope.
    window.location.href = url
}
