internal fun Pair<String, String>.plinToText() = "${this.first}|${this.second}"
private fun String?.toIntOrZero() = this?.toIntOrNull() ?: 0

private fun currentEventName(): String {
    val now = Clock.System.now().toLocalDateTime(TimeZone.currentSystemDefault())
    val year = now.year
    return when (now.month) {
        Month.APRIL, Month.MAY, Month.JUNE -> "Moots 1 $year"
        Month.JULY, Month.AUGUST -> "Summoning $year"
        Month.OCTOBER -> "Moots 2 $year"
        else -> "Special? $year"
    }
}

private fun EnergyType.englishName(): String = when (this) {
    EnergyType.ELEMENTAL_MANA -> "Elemental Mana"
    EnergyType.SPIRITUAL_MANA -> "Spiritual Mana"
    EnergyType.ELEMENTAL_RITUAL -> "Elemental Ritual Mana"
    EnergyType.SPIRITUAL_RITUAL -> "Spiritual Ritual Mana"
    EnergyType.WILLPOWER -> "Willpower"
    EnergyType.INSPIRATION -> "Inspiration"
}

private fun MundaneSkill.englishName(): String = when (this) {
    MundaneSkill.SCROLL_PAPER -> "Scroll Paper"
    MundaneSkill.SKILL_RESEARCH_BOOK -> "Empty Skill Research Book"
    MundaneSkill.BOOK_OF_EXPERIENCES -> "Empty Book of Experiences"
    MundaneSkill.MARRIAGE_JEWELRY -> "Marriage Jewelry"
}

internal fun MundaneSkill.englishEffect(): String = when (this) {
    MundaneSkill.SCROLL_PAPER ->
        "Can be used for 'Runic Scroll Crafting' or 'Glyph Scroll Crafting'. " +
            "Scroll Paper does not expire unlike other mundane items. " +
            "You will receive the paper at next event check-in."
    MundaneSkill.SKILL_RESEARCH_BOOK ->
        "If a person makes notes about their research into an extra skill for 3 " +
            "consecutive events, they can learn that skill afterwards without a teacher."
    MundaneSkill.BOOK_OF_EXPERIENCES ->
        "If a person makes personal notes about their experiences around this event, " +
            "they receive 0.25 extra XP after this event. Only 1 book can be used per event per target player."
    MundaneSkill.MARRIAGE_JEWELRY ->
