private fun calculateTotalCraftEnergy(resources: Map<Int, ItemCraftResourceForm>): Map<EnergyType, Int> {
    val result = mutableMapOf<EnergyType, Int>()
    resources.values.forEach { r ->
        result[r.energyType] = (result[r.energyType] ?: 0) + r.energyAmount.toIntOrZero()
    }
    return result
}

private fun calculateTotalImbueEnergy(resources: Map<Int, ImbueResourceForm>): Map<EnergyType, Int> {
    val result = mutableMapOf<EnergyType, Int>()
    resources.values.forEach { r ->
        result[r.energyType] = (result[r.energyType] ?: 0) + r.energyAmount.toIntOrZero()
    }
    return result
}

private fun calculateTotalRechargeEnergy(resources: Map<Int, RechargeResourceForm>): Map<EnergyType, Int> {
    val result = mutableMapOf<EnergyType, Int>()
    resources.values.forEach { r ->
        result[r.energyType] = (result[r.energyType] ?: 0) + r.energyAmount.toIntOrZero()
    }
    return result
}

private fun ImbueResourceForm.getPower(): String =
    (imbueType?.powerText
        ?.replace("[AMOUNT]", amount)
        ?.replace("[VALUE]", imbueOption?.displayName.orEmpty()) ?: "") + " $skillSpell"

// ---------------------------------------------------------------------------
// ItemCraftForm
// ---------------------------------------------------------------------------

fun ItemCraftForm.toVortexCard(tempItin: String): VortexItemCardDisplay =
    VortexItemCardDisplay(
        header = "temporary item card",
        itemName = name,
        itemDescription = description,
        energyUsed = calculateTotalCraftEnergy(resources),
        craftResources = resources.values.map { r ->
            CraftResourceEntry(
                resourceAmount = r.resourceAmount,
                resourceType = r.resourceType?.name.orEmpty(),
                energyAmount = r.energyAmount,
                energyType = r.energyType.name,
                plin = r.plin.first,
                chin = r.plin.second,
            )
        },
        imbueCap = imbueCap,
        createdBy = resources.map { it.value.plin.plinToText() }.distinctBy { it }.joinToString("+"),
        tempItin = tempItin,
        power = null,
        event = currentEventName(),
    )

fun ItemCraftForm.toResourcesText(): String =
    resources.map {
        "${it.value.resourceAmount} ${it.value.resourceType?.resourceName.orEmpty()} " +
            "processed with ${it.value.energyAmount} ${it.value.energyType.englishName()} " +
            "by ${it.value.plin.plinToText()}"
    }.joinToString(separator = "\n")

// ---------------------------------------------------------------------------
// ImbueForm
// ---------------------------------------------------------------------------

fun ImbueForm.toVortexCard(imbueId: String): VortexItemCardDisplay =
    VortexItemCardDisplay(
        header = if (!isPerson) "temporary item imbue card" else "temporary person imbue card",
        targetItin = targetItin,
        targetPlin = targetPlin?.plinToText(),
        energyUsed = calculateTotalImbueEnergy(imbueResources),
        imbueResourceEntries = imbueResources.values.map { r ->
            ImbueResourceEntry(
                energyAmount = r.energyAmount,
                energyType = r.energyType.name,
                imbueTypeId = r.imbueType?.id.orEmpty(),
                imbueOptionName = r.imbueOption?.name.orEmpty(),
                amount = r.amount,
                skillSpell = r.skillSpell,
                headImbuerPlin = r.headImbuerPlin.first,
                headImbuerChin = r.headImbuerPlin.second,
                suppliers = r.energySuppliers.values.map { s ->
                    SerializedSupplier(
                        amount = s.amount,
                        plin = s.plin.first,
                        chin = s.plin.second,
                    )
                },
            )
        },
        createdBy = imbueResources.map { it.value.headImbuerPlin.plinToText() }.distinctBy { it }.joinToString("+"),
        imbueId = imbueId,
        power = imbueResources.entries.map { it.value.getPower() }.joinToString(separator = "\n"),
        event = currentEventName(),
    )

fun ImbueForm.toResourcesText(): String =
    imbueResources.map { rs ->
        "${rs.value.amount}x ${rs.value.imbueType?.englishName.orEmpty()} " +
            "${rs.value.imbueOption?.displayName.orEmpty()} ${rs.value.skillSpell} " +
            "by ${rs.value.headImbuerPlin.plinToText()}" +
            "\nRequired energy: ${rs.value.energyAmount} ${rs.value.energyType.englishName()} main imbuer ${rs.value.headImbuerPlin.plinToText()}" +
            "\nSupplied energy:\n" +
            rs.value.energySuppliers.map {
                "       ${it.value.amount} ${rs.value.energyType.englishName()} by ${it.value.plin.plinToText()}"
            }.joinToString(separator = "\n")
    }.joinToString("\n\n")

