// ---------------------------------------------------------------------------
// MundaneForm
// ---------------------------------------------------------------------------

fun MundaneForm.toVortexCard(itemId: String? = null): VortexItemCardDisplay {
    val targetText = when {
        selectedSkill?.requiresSecondPlin == true ->
            "${targetPlin.plinToText()} + ${targetPlin2.plinToText()}"
        selectedSkill?.requiresTargetPlin == true ->
            targetPlin.plinToText()
        else -> null
    }
    return VortexItemCardDisplay(
        header = "Mundane Item",
        tempItin = itemId,
        itemName = selectedSkill?.englishName(),
        itemDescription = null,
        createdBy = crafterPlin.plinToText(),
        targetPlin = targetText,
        power = selectedSkill?.englishEffect(),
        event = currentEventName(),
    )
}

fun MundaneForm.toResourcesText(): String {
    val qtyPart = if (selectedSkill?.hasQuantity == true) " x$quantity" else ""
    val baseText = "${selectedSkill?.englishName().orEmpty()}$qtyPart, by ${crafterPlin.plinToText()}"
    val suppliers = inspirationSuppliers.values.filter { it.plin.first.isNotBlank() }
    return if (suppliers.isNotEmpty()) {
        baseText + "\nInspiration supplied by:\n" +
            suppliers.joinToString("\n") { "  ${it.amount} Inspiration by ${it.plin.plinToText()}" }
    } else {
        "$baseText (materials used)"
    }
}
