package com.coding.va.selfhelp.data.models

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable

/**
 * Wrapper returned by GET /auth/OAuth2.
 * The API returns: { "class": "List", "url": "/auth/OAuth2", "list": [...] }
 */
@Serializable
data class SocialProvidersResponse(
    val list: List<SocialProviderEntity>,
)

@Serializable
data class SocialProviderEntity(
    val name: String,
    @SerialName("loginRedirect") val authUri: String,
    @SerialName("urlLoginCode") val url: String,
)

@Serializable
data class AuthTokenEntity(
    val token: String? = null,
    val jwt: String? = null,
    @SerialName("access_token") val accessToken: String? = null,
) {
    fun extractToken(): String? = token ?: jwt ?: accessToken
}
