package com.coding.va.selfhelp.presentation.screens.history

import androidx.compose.ui.text.AnnotatedString
import androidx.compose.ui.text.SpanStyle
import androidx.compose.ui.text.buildAnnotatedString
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.text.withStyle
import com.coding.va.selfhelp.i18n.AppStrings
import com.coding.va.selfhelp.presentation.methods.SavedCreation
import com.coding.va.selfhelp.presentation.methods.SavedCreations
import com.coding.va.selfhelp.presentation.screens.history.model.HistoryItemDisplay
import com.coding.va.selfhelp.presentation.screens.history.model.HistoryScreenDisplay
import com.coding.va.selfhelp.theme.vortexRed

object HistoryDisplayMapper {

    fun mapDisplay(savedCreations: SavedCreations, strings: AppStrings): HistoryScreenDisplay.Display =
        HistoryScreenDisplay.Display(
            title = strings.history.title,
            subtitle = strings.history.subtitle,
            emptyMessage = strings.history.emptyMessage,
            items = savedCreations.items.reversed().map { mapItem(it, strings) },
            backButton = strings.common.backToHome,
        )

    fun mapFailure(strings: AppStrings): HistoryScreenDisplay.Display =
        HistoryScreenDisplay.Display(
            title = strings.history.title,
            subtitle = strings.history.subtitle,
            emptyMessage = strings.history.emptyMessage,
            items = emptyList(),
            backButton = strings.common.backToHome,
        )

    private fun mapItem(creation: SavedCreation, strings: AppStrings): HistoryItemDisplay {
        val craftingId = creation.vortexCard?.tempItin ?: creation.vortexCard?.imbueId
        val typeCode = creation.cardCode.substringAfter("+", "").take(1)
        val canRepeat = typeCode == "1" || typeCode == "2" || typeCode == "3"
        val repeatLabel = when (typeCode) {
            "1" -> strings.history.craftAgainButton
            else -> strings.history.imbueAgainButton
        }
        return HistoryItemDisplay(
            cardCode = creation.cardCode,
            kindOfCreation = creation.name,
            name = creation.readableText,
            plinText = creation.vortexCard?.targetPlin?.let { "Plin: $it" },
            printerCodeLabel = strings.history.printerCodeLabel,
            vortexCard = creation.vortexCard,
            isExpanded = false,
            resourcesText = creation.resourcesText,
            notes = creation.notes,
            envelopeInstruction = craftingId?.let { buildEnvelopeInstruction(it, strings) },
            noCardDetailsText = strings.history.noCardDetailsText,
            canRepeat = canRepeat,
            repeatButtonLabel = repeatLabel,
        )
    }

    private fun buildEnvelopeInstruction(craftingId: String, strings: AppStrings): AnnotatedString =
        buildAnnotatedString {
            append(strings.history.envelopeInstructionPrefix)
            withStyle(style = SpanStyle(color = vortexRed, fontWeight = FontWeight.Bold)) {
                append(craftingId)
            }
            append(strings.history.envelopeInstructionSuffix)
        }
}
