@Composable
fun LandingContent(
    display: LandingScreenDisplay,
    onEvent: ((LandingScreenEvent) -> Unit)? = null
) {
    val uriHandler = LocalUriHandler.current
    val typography = VortexTypography()
    val a11y = LocalStrings.current.a11y

    Surface(modifier = Modifier.fillMaxSize().background(Color.White)) {
        display.errorBox?.let {
            ErrorBox(
                display = it,
                onConfirmation = { },
                onDismissRequest = { onEvent?.invoke(LandingScreenEvent.DismissError) })
        }

        Column(modifier = Modifier.fillMaxWidth().verticalScroll(rememberScrollState()).padding(top = 24.dp, bottom = 12.dp).padding(horizontal = 24.dp)) {

            Row(modifier = Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
                Text(
                    modifier = Modifier
                        .fillMaxWidth(0.8f)
                        .semantics { heading() },
                    text = display.title,
                    style = typography.headlineLarge,
                )
                Spacer(modifier = Modifier.weight(1f))
                if (getPlatform() == TYPE.DESKTOP) {
                    var menuExpanded by remember { mutableStateOf(false) }
                    Box(modifier = Modifier.width(50.dp)) {
                        UnstyledDropdownMenu(onExpandRequest = { menuExpanded = true }) {
                            Box(
                                Modifier
                                    .fillMaxWidth()
                                    .semantics {
                                        role = Role.Button
                                        contentDescription = a11y.menuButton
                                    }
                                    .clickable { menuExpanded = !menuExpanded },
                            ) {
                                Image(
                                    modifier = Modifier.size(65.dp),
                                    painter = painterResource(Res.drawable.vortex_logo),
                                    contentDescription = null,
                                )
                            }

                            UnstyledDropdownMenuPanel(
                                expanded = menuExpanded,
                                onDismissRequest = { menuExpanded = false },
                                modifier = Modifier.padding(vertical = 4.dp)
                                    .width(240.dp)
                                    .shadow(4.dp, RoundedCornerShape(8.dp))
                                    .clip(RoundedCornerShape(8.dp))
                                    .background(Color.White),
                                enter = scaleIn(
                                    animationSpec = tween(durationMillis = 120, easing = LinearOutSlowInEasing),
                                    initialScale = 0.8f,
                                    transformOrigin = TransformOrigin(0f, 0f)
                                ) + fadeIn(tween(durationMillis = 30)),
                                exit = scaleOut(
                                    animationSpec = tween(durationMillis = 1, delayMillis = 75),
                                    targetScale = 1f
                                ) + fadeOut(tween(durationMillis = 75))
                            ) {
                                Column(modifier = Modifier.verticalScroll(rememberScrollState())) {
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        modifier = Modifier.padding(horizontal = 8.dp, vertical = 2.dp)
                                    ) {
                                        Text(
                                            text = display.menuDisplay.header,
                                            style = typography.bodyLarge,
                                            textAlign = TextAlign.Center,
                                            modifier = Modifier.fillMaxWidth().padding(vertical = 8.dp, horizontal = 4.dp)
                                        )
                                    }
                                    when (display.menuDisplay) {
                                        is MenuDisplay.Locked -> {
                                            OutlinedTextField(
                                                modifier = Modifier.padding(horizontal = 8.dp, vertical = 2.dp),
                                                isError = false,
                                                value = display.menuDisplay.password,
                                                visualTransformation = PasswordVisualTransformation(),
                                                onValueChange = {
                                                    onEvent?.invoke(
                                                        LandingScreenEvent.MenuChange(display.menuDisplay.copy(password = it))
                                                    )
                                                },
                                                label = { Text(text = display.menuDisplay.passwordLabel) }
                                            )
                                        }

                                        is MenuDisplay.UnLocked -> {
                                            Row(
                                        modifier = Modifier.padding(horizontal = 8.dp, vertical = 2.dp),
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Text(text = display.menuDisplay.printerModeLabel)
                                        Button(
                                            modifier = Modifier.padding(horizontal = 4.dp),
                                            onClick = {
                                                val newMode = if (display.menuDisplay.printerMode == "usb") "network" else "usb"
                                                onEvent?.invoke(
                                                    LandingScreenEvent.MenuChange(display.menuDisplay.copy(printerMode = newMode))
                                                )
                                            }
                                        ) {
                                            Text(text = if (display.menuDisplay.printerMode == "usb") display.menuDisplay.printerModeUsbLabel else display.menuDisplay.printerModeNetworkLabel)
                                        }
                                    }
                                            if (display.menuDisplay.printerMode == "network") {
                                                OutlinedTextField(
                                                    modifier = Modifier.padding(horizontal = 8.dp, vertical = 2.dp),
                                                    isError = false,
                                                    value = display.menuDisplay.printerIp,
                                                    onValueChange = {
                                                        onEvent?.invoke(
                                                            LandingScreenEvent.MenuChange(display.menuDisplay.copy(printerIp = it))
                                                        )
                                                    },
                                                    label = { Text(text = display.menuDisplay.printerIpLabel) }
                                                )
                                            }
                                            Row(
                                                modifier = Modifier.padding(horizontal = 8.dp, vertical = 2.dp),
                                                verticalAlignment = Alignment.CenterVertically
                                            ) {
                                                Checkbox(
                                                    checked = display.menuDisplay.printerEnabled,
                                                    onCheckedChange = {
                                                        onEvent?.invoke(
                                                            LandingScreenEvent.MenuChange(display.menuDisplay.copy(printerEnabled = it))
                                                        )
                                                    },
                                                )
                                                Text(text = display.menuDisplay.printerEnabledLabel)
                                            }
                                            Row(
                                                modifier = Modifier.padding(horizontal = 8.dp, vertical = 2.dp),
                                                verticalAlignment = Alignment.CenterVertically
                                            ) {
                                                Checkbox(
                                                    checked = display.menuDisplay.printerCodeEnabled,
                                                    onCheckedChange = {
                                                        onEvent?.invoke(
                                                            LandingScreenEvent.MenuChange(display.menuDisplay.copy(printerCodeEnabled = it))
                                                        )
                                                    },
                                                )
                                                Text(text = display.menuDisplay.printerCodeEnabledLabel)
                                            }
                                            OutlinedTextField(
                                                modifier = Modifier.padding(horizontal = 8.dp, vertical = 2.dp),
                                                isError = false,
                                                value = display.menuDisplay.sheetId,
                                                onValueChange = {
                                                    onEvent?.invoke(
                                                        LandingScreenEvent.MenuChange(display.menuDisplay.copy(sheetId = it))
                                                    )
                                                },
                                                label = { Text(text = display.menuDisplay.sheetIpLabel) }
                                            )
                                            OutlinedTextField(
                                                modifier = Modifier.padding(horizontal = 8.dp, vertical = 2.dp),
                                                isError = false,
                                                value = display.menuDisplay.deviceIp,
                                                enabled = false,
                                                onValueChange = {},
                                                label = { Text(text = display.menuDisplay.deviceIpLabel) }
                                            )
                                            Button(
                                                modifier = Modifier.fillMaxWidth().padding(horizontal = 8.dp, vertical = 2.dp),
                                                onClick = {
                                                    onEvent?.invoke(LandingScreenEvent.MenuSave)
                                                }) {
                                                Text(text = display.menuDisplay.save)
                                            }
                                            Button(
                                                modifier = Modifier.fillMaxWidth().padding(horizontal = 8.dp, vertical = 2.dp),
                                                onClick = {
                                                    onEvent?.invoke(LandingScreenEvent.MenuLock)
                                                }) {
                                                Text(text = display.menuDisplay.lock)
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                } else {
                    Image(
                        modifier = Modifier.size(65.dp),
                        painter = painterResource(Res.drawable.vortex_logo),
                        contentScale = ContentScale.FillWidth,
                        contentDescription = null,
                    )
                }
            }
            Text(text = display.description, style = typography.titleLarge)

            display.serviceMessage?.let {
                Text(
                    modifier = Modifier
                        .padding(vertical = 8.dp)
                        .background(Color(0xFFEACFBC), RoundedCornerShape(4.dp))
                        .padding(8.dp)
                        .semantics { liveRegion = LiveRegionMode.Polite },
                    text = it,
                    style = typography.bodyMedium
                )
            }

            display.tasks.chunked(2).forEach { chunk ->
                Row {
                    chunk.getOrNull(0)?.let { item ->
                        Button(
                            modifier = Modifier.height(100.dp).weight(1f).padding(end = 4.dp, top = 4.dp, bottom = 4.dp),
                            onClick = { onEvent?.invoke(item.action) }) {
                            Text(text = item.title, style = typography.labelLarge)
                        }
                    }
                    chunk.getOrNull(1)?.let { item ->
                        Button(
                            modifier = Modifier.height(100.dp).weight(1f).padding(start = 4.dp, top = 4.dp, bottom = 4.dp),
                            onClick = { onEvent?.invoke(item.action) }) {
                            Text(text = item.title, style = typography.labelLarge)
                        }
                    } ?: Spacer(modifier = Modifier.weight(1f))
                }
            }

            display.printField?.let { printField ->
                Box {
                    Column {
                        Text(
                            text = display.printDescription.orEmpty(),
                            style = typography.bodyLarge,
                            modifier = Modifier.fillMaxWidth().padding(top = 56.dp).padding(vertical = 8.dp)
                        )
                        OutlinedTextField(
                            modifier = Modifier.width(200.dp),
                            value = display.cardCode,
                            placeholder = { Text(text = printField.hint) },
                            onValueChange = { code ->
                                onEvent?.invoke(
                                    LandingScreenEvent.CardCode(code.uppercase())
                                )
                            },
                            label = { Text(text = printField.label) }
                        )
                        Button(
                            modifier = Modifier.padding(vertical = 2.dp),
                            enabled = display.attemptPrintButton?.loading == false,
                            onClick = {
                                onEvent?.invoke(LandingScreenEvent.PrintCard)
                            }) {
                            Text(text = display.attemptPrintButton?.label.orEmpty())
                        }
                    }
                }
            }

            // "Login with VOID" navigation button — mobile only
            display.loginButton?.let { label ->
                Button(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(top = 12.dp),
                    onClick = { onEvent?.invoke(LandingScreenEvent.NavigateToLogin) }
                ) {
                    Text(text = label, style = typography.bodyMedium)
                }
            }

            // "My Character" button — shown when logged in with active character
            display.myCharacterButton?.let { label ->
                Button(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(top = 8.dp),
                    onClick = { onEvent?.invoke(LandingScreenEvent.NavigateToCharacterDetail) }
                ) {
                    Text(text = label, style = typography.bodyMedium)
                }
            }
            Spacer(modifier = Modifier.height(24.dp))

            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween
            ) {
                // Language toggle button — always visible bottom-left
                Button(
                    modifier = Modifier
                        .padding(top = 4.dp)
                        .height(if (getPlatform() == TYPE.DESKTOP) 100.dp else 40.dp)
                        .onlyDesktop { width(100.dp) },
                    enabled = true,
                    onClick = { onEvent?.invoke(LandingScreenEvent.ToggleLanguage) }
                ) {
                    Text(
                        style = if (getPlatform() == TYPE.DESKTOP) typography.labelLarge else typography.bodySmall,
                        text = display.languageToggleLabel
                    )
                }

                // Feedback button — bottom-right, mobile only
                if (display.feedbackButton != null && display.feedbackUrl != null) {
                    Button(
                        modifier = Modifier.height(40.dp).padding(top = 4.dp),
                        enabled = true,
                        onClick = {
                            uriHandler.openUri(uri = display.feedbackUrl)
                        }) {
                        Text(style = typography.bodySmall, text = display.feedbackButton)
                    }
                }
            }
        }
    }
}


