package com.coding.va.selfhelp.presentation.screens.login

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import co.touchlab.kermit.Logger
import com.coding.va.selfhelp.domain.exceptions.AccountNotLinkedException
import com.coding.va.selfhelp.auth.generatePkce
import com.coding.va.selfhelp.auth.OAUTH_CALLBACK_SCHEME
import com.coding.va.selfhelp.auth.OAUTH_CALLBACK_URI
import com.coding.va.selfhelp.auth.OAuthBridge
import com.coding.va.selfhelp.di.launchOAuthBrowser
import com.coding.va.selfhelp.di.signInWithApple
import com.coding.va.selfhelp.di.signInWithGoogle
import com.coding.va.selfhelp.domain.model.SocialProvider
import com.coding.va.selfhelp.domain.use_cases.GetSocialProvidersUseCase
import com.coding.va.selfhelp.domain.use_cases.LoginWithAppleUseCase
import com.coding.va.selfhelp.domain.use_cases.LoginWithGoogleUseCase
import com.coding.va.selfhelp.domain.use_cases.LoginWithProviderUseCase
import com.coding.va.selfhelp.i18n.AppStrings
import com.coding.va.selfhelp.presentation.screens.login.model.LoginScreenDisplay
import com.coding.va.selfhelp.presentation.screens.login.model.LoginScreenEvent
import com.coding.va.selfhelp.presentation.screens.mainscreen.actions.MainActions
import com.coding.va.selfhelp.presentation.screens.mainscreen.destinations.MainDestinations
import io.ktor.http.encodeURLQueryComponent
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import kotlin.random.Random
import org.koin.android.annotation.KoinViewModel

private val log = Logger.withTag("LoginFlow")

@KoinViewModel
class LoginViewModel(
    private val getSocialProviders: GetSocialProvidersUseCase,
    private val loginWithProvider: LoginWithProviderUseCase,
    private val loginWithGoogle: LoginWithGoogleUseCase,
    private val loginWithApple: LoginWithAppleUseCase,
    private val strings: AppStrings,
) : ViewModel() {

    private val _display = MutableStateFlow<LoginScreenDisplay>(LoginDisplayProvider.loading())
    val display = _display.asStateFlow()

    private var mainActions: MainActions? = null

    // Cached provider list so we don't re-fetch on every button press.
    private var cachedProviders: List<SocialProvider> = emptyList()

    // OAuth state tracking — set before opening the browser, cleared after callback.
    private var pendingOAuthState: String? = null
    private var pendingProvider: SocialProvider? = null
    private var pendingCodeVerifier: String? = null

    fun initVM(actions: MainActions) {
        mainActions = actions
        viewModelScope.launch { loadProviders() }
        viewModelScope.launch { listenForOAuthCallback() }
    }

    private suspend fun loadProviders() {
        log.d { "Login - loadSocialProviders: calling VOID API" }
        _display.emit(LoginDisplayProvider.loading())

        getSocialProviders()
            .onSuccess { providers ->
                log.d { "Login - loadSocialProviders: SUCCESS — ${providers.size} providers: ${providers.map { it.name }}" }
                cachedProviders = providers
                _display.emit(LoginDisplayProvider.display(strings, providers))
            }
            .onFailure { err ->
                log.e(err) { "Login - loadSocialProviders: FAILED — ${err.message}" }
                _display.emit(LoginDisplayProvider.error(strings))
            }
    }

    private suspend fun listenForOAuthCallback() {
        log.d { "Login - OAuthBridge callback listener started" }
        OAuthBridge.callbacks.collect { callback ->
            log.d { "Login - OAuthBridge callback received: code=${callback.code.take(8)}… state=${callback.state}" }

            val state = pendingOAuthState ?: run {
                log.w { "Login - No pending OAuth state — ignoring callback" }
                return@collect
            }
            val provider = pendingProvider ?: run {
                log.w { "Login - No pending provider — ignoring callback" }
                return@collect
            }

            if (callback.state != state) {
                log.e { "Login - State mismatch! expected=$state received=${callback.state}" }
                pendingOAuthState = null
                pendingProvider = null
                _display.emit(LoginDisplayProvider.error(strings))
                return@collect
            }

            log.d { "Login - State verified — exchanging code for JWT via provider: ${provider.name}" }
            pendingOAuthState = null
            pendingProvider = null
            val codeVerifier = pendingCodeVerifier
            pendingCodeVerifier = null

            loginWithProvider(provider, callback.code, OAUTH_CALLBACK_URI, codeVerifier)
                .onSuccess { jwt ->
                    log.d { "Login - JWT received (first 12 chars): ${jwt.take(12)}…" }
                    mainActions?.navigate(MainDestinations.CharacterSelect)
                }
                .onFailure { err ->
                    log.e(err) { "Login - Token exchange failed: ${err.message}" }
                    if (err is AccountNotLinkedException) {
                        _display.emit(LoginDisplayProvider.unlinkedAccount(strings))
                    } else {
                        _display.emit(LoginDisplayProvider.error(strings))
                    }
                }
        }
    }

    fun onEvent(event: LoginScreenEvent) {
        viewModelScope.launch {
            when (event) {
                is LoginScreenEvent.LoginWithGoogle -> {
                    log.d { "Login - LoginWithGoogle event — launching native Google Sign-In…" }
                    val currentDisplay = _display.value as? LoginScreenDisplay.Display
                    if (currentDisplay != null) {
                        _display.emit(LoginDisplayProvider.authenticating(currentDisplay))
                    }
                    signInWithGoogle()
                        .onSuccess { idToken ->
                            log.d { "Login - Native Google Sign-In OK — exchanging ID token with VOID backend…" }
                            loginWithGoogle(idToken)
                                .onSuccess { jwt ->
                                    log.d { "Login - JWT received (first 12 chars): ${jwt.take(12)}…" }
                                    mainActions?.navigate(MainDestinations.CharacterSelect)
                                }
                                .onFailure { err ->
                                    log.e(err) { "Login - Google token exchange failed: ${err.message}" }
                                    if (err is AccountNotLinkedException) {
                                        _display.emit(LoginDisplayProvider.unlinkedAccount(strings))
                                    } else {
                                        _display.emit(LoginDisplayProvider.error(strings))
                                    }
                                }
                        }
                        .onFailure { err ->
                            log.e(err) { "Login - Native Google Sign-In failed: ${err.message}" }
                            _display.emit(LoginDisplayProvider.error(strings))
                        }
                }

                is LoginScreenEvent.LoginWithApple -> {
                    log.d { "Login - LoginWithApple event — launching native Apple Sign-In…" }
                    val currentDisplay = _display.value as? LoginScreenDisplay.Display
                    if (currentDisplay != null) {
                        _display.emit(LoginDisplayProvider.authenticating(currentDisplay))
                    }
                    signInWithApple()
                        .onSuccess { idToken ->
                            log.d { "Login - Native Apple Sign-In OK — exchanging identity token with VOID backend…" }
                            loginWithApple(idToken)
                                .onSuccess { jwt ->
                                    log.d { "Login - JWT received (first 12 chars): ${jwt.take(12)}…" }
                                    mainActions?.navigate(MainDestinations.CharacterSelect)
                                }
                                .onFailure { err ->
                                    log.e(err) { "Login - Apple token exchange failed: ${err.message}" }
                                    if (err is AccountNotLinkedException) {
                                        _display.emit(LoginDisplayProvider.unlinkedAccount(strings))
                                    } else {
                                        _display.emit(LoginDisplayProvider.error(strings))
                                    }
                                }
                        }
                        .onFailure { err ->
                            log.e(err) { "Login - Native Apple Sign-In failed: ${err.message}" }
                            _display.emit(LoginDisplayProvider.error(strings))
                        }
                }

                is LoginScreenEvent.LoginWithProvider -> {
                    log.d { "Login - LoginWithProvider event: providerName=${event.providerName}" }
                    log.d { "Login - cachedProviders count: ${cachedProviders.size} — names: ${cachedProviders.map { it.name }}" }

                    val provider = cachedProviders.firstOrNull { it.name == event.providerName }
                    if (provider == null) {
                        log.w { "Login - Provider '${event.providerName}' not in cache — re-fetching" }
                        loadProviders()
                        return@launch
                    }

                    log.d { "Login - Provider found: ${provider.name} — launching browser OAuth flow" }

                    val currentDisplay = _display.value as? LoginScreenDisplay.Display
                    if (currentDisplay != null) {
                        _display.emit(LoginDisplayProvider.authenticating(currentDisplay))
                    }

                    log.d { "Login - Provider authUri (raw): ${provider.authUri}" }

                    val state = Random.nextBytes(16).joinToString("") { byte ->
                        val hex = (byte.toInt() and 0xFF).toString(16)
                        if (hex.length == 1) "0$hex" else hex
                    }

                    val (codeVerifier, codeChallenge) = generatePkce()

                    val authUri = provider.authUri
                        .replace("STATE", state)
                        .replace("CALLBACK", OAUTH_CALLBACK_URI.encodeURLQueryComponent()) +
                        "&code_challenge=$codeChallenge&code_challenge_method=S256"

                    log.d { "Login - authUri after substitution: $authUri" }
                    log.d { "Login - callbackScheme: $OAUTH_CALLBACK_SCHEME | callbackUri: $OAUTH_CALLBACK_URI" }

                    pendingOAuthState = state
                    pendingProvider = provider
                    pendingCodeVerifier = codeVerifier

                    log.d { "Login - Calling launchOAuthBrowser…" }
                    launchOAuthBrowser(authUri, OAUTH_CALLBACK_SCHEME)
                    log.d { "Login - launchOAuthBrowser returned" }
                }

                is LoginScreenEvent.RetryLoad -> {
                    loadProviders()
                }

                is LoginScreenEvent.Back -> {
                    mainActions?.back()
                }

            }
        }
    }
}
