@Composable
fun HistoryContent(
    display: Display,
    onEvent: ((HistoryEvent) -> Unit)? = null,
) {
    val typography = VortexTypography()

    Column(
        modifier = Modifier
            .fillMaxWidth()
            .padding(horizontal = 16.dp, vertical = 12.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        Text(
            text = display.title,
            style = typography.headlineLarge,
            modifier = Modifier.semantics { heading() },
        )
        Text(
            text = display.subtitle,
            style = typography.bodySmall,
            color = secondaryTextColor,
        )
    }

    if (display.items.isEmpty()) {
        Column(
            modifier = Modifier
                .padding(horizontal = 16.dp, vertical = 24.dp)
                .semantics { liveRegion = LiveRegionMode.Polite },
        ) {
            Text(text = display.emptyMessage, style = typography.bodyMedium)
        }
    } else {
        display.items.forEachIndexed { index, item ->
            HistoryListItem(
                item = item,
                index = index,
                onClick = { onEvent?.invoke(HistoryEvent.ToggleExpand(index)) },
                onEvent = onEvent,
            )
            Divider(color = dividerColor, thickness = 1.dp)
        }
    }
}

@Composable
private fun HistoryListItem(
    item: HistoryItemDisplay,
    index: Int,
    onClick: () -> Unit,
    onEvent: ((HistoryEvent) -> Unit)? = null,
) {
    val typography = VortexTypography()
    val a11y = LocalStrings.current.a11y

    Column(
        modifier = Modifier
            .fillMaxWidth()
            .semantics {
                role = Role.Button
                stateDescription = if (item.isExpanded) a11y.expanded else a11y.collapsed
            }
            .clickable(onClick = onClick)
            .padding(horizontal = 16.dp, vertical = 10.dp),
    ) {
        Row(modifier = Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
            Column(modifier = Modifier.weight(1f)) {
                Text(
                    text = item.kindOfCreation,
                    style = typography.bodySmall,
                    color = secondaryTextColor,
                )
                item.name?.let {
                    Text(
                        text = it,
                        style = typography.bodyLarge,
                        fontWeight = FontWeight.SemiBold,
                    )
                }
                item.plinText?.let {
                    Text(
                        text = it,
                        style = typography.bodyMedium,
                    )
                }
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Text(
                        text = item.printerCodeLabel,
                        style = typography.bodySmall,
                        color = secondaryTextColor,
                    )
                    Text(
                        text = item.cardCode,
                        style = typography.bodyMedium,
                        fontFamily = FontFamily.Monospace,
                    )
                }
            }
            Text(
                text = if (item.isExpanded) "▲" else "▼",
                style = typography.bodyMedium,
                color = vortexRed,
            )
        }

        AnimatedVisibility(
            visible = item.isExpanded,
            enter = expandVertically(),
            exit = shrinkVertically(),
        ) {
            Column(modifier = Modifier.fillMaxWidth().padding(top = 12.dp)) {
                if (item.resourcesText != null) {
                    CreationSummaryDetail(
                        resources = item.resourcesText,
                        notes = item.notes ?: "",
                        modifier = Modifier
                            .fillMaxWidth()
                            .clip(RoundedCornerShape(8.dp))
                            .background(Color(0xFFF5F5F5))
                            .padding(12.dp),
                    )
                    Spacer(modifier = Modifier.height(8.dp))
                    item.envelopeInstruction?.let {
                        Text(
                            text = it,
                            style = typography.bodySmall,
                            modifier = Modifier.padding(horizontal = 4.dp),
                        )
                    }
                    Spacer(modifier = Modifier.height(12.dp))
                }

                if (item.canRepeat) {
                    Button(
                        modifier = Modifier.fillMaxWidth(),
                        onClick = { onEvent?.invoke(HistoryEvent.RepeatCreation(index)) },
                        colors = ButtonDefaults.buttonColors(backgroundColor = vortexRed),
                    ) {
                        Text(
                            text = item.repeatButtonLabel,
                            color = Color.White,
                        )
                    }
                    Spacer(modifier = Modifier.height(8.dp))
                }

                if (item.vortexCard != null) {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clip(RoundedCornerShape(8.dp))
                            .background(Color(0xFFF5F5F5))
                            .padding(8.dp),
                    ) {
                        VortexItemCardUIFront(display = item.vortexCard, modifier = Modifier.fillMaxWidth())
                        Spacer(modifier = Modifier.height(8.dp))
                        VortexItemCardUIBack(display = item.vortexCard, modifier = Modifier.fillMaxWidth())
                        Spacer(modifier = Modifier.height(8.dp))
                    }
                } else if (item.resourcesText == null) {
                    Text(
                        modifier = Modifier.padding(top = 8.dp),
                        text = item.noCardDetailsText,
                        style = typography.bodySmall,
                        color = secondaryTextColor,
                    )
                }
            }
        }
    }
}
