// ---------------------------------------------------------------------------
// EnergyType
// ---------------------------------------------------------------------------

fun EnergyType.localizedName(strings: AppStrings): String = when (this) {
    EnergyType.ELEMENTAL_MANA -> strings.energyTypes.elementalMana
    EnergyType.SPIRITUAL_MANA -> strings.energyTypes.spiritualMana
    EnergyType.ELEMENTAL_RITUAL -> strings.energyTypes.elementalRitual
    EnergyType.SPIRITUAL_RITUAL -> strings.energyTypes.spiritualRitual
    EnergyType.WILLPOWER -> strings.energyTypes.willpower
    EnergyType.INSPIRATION -> strings.energyTypes.inspiration
}

// ---------------------------------------------------------------------------
// EntryType
// ---------------------------------------------------------------------------

fun EntryType.localizedName(strings: AppStrings): String = when (this) {
    EntryType.CRAFT_ITEM -> strings.entryTypes.craftItem
    EntryType.IMBUE_ITEM -> strings.entryTypes.imbueItem
    EntryType.IMBUE_PERSON -> strings.entryTypes.imbuePerson
    EntryType.RECHARGE_ITEM -> strings.entryTypes.rechargeItem
    EntryType.MUNDANE_ITEM -> strings.entryTypes.mundaneItem
}

