package com.coding.va.selfhelp.di

import com.coding.va.selfhelp.i18n.AppStrings
import com.coding.va.selfhelp.i18n.LanguageRepository
import org.koin.core.annotation.ComponentScan
import org.koin.core.annotation.Factory
import org.koin.core.annotation.Module

@Module
@ComponentScan("com.coding.va.selfhelp")
class AppModule {

    @Factory
    fun appStrings(languageRepository: LanguageRepository): AppStrings =
        languageRepository.getStrings()
}
