package com.coding.va.selfhelp.data.network

import com.coding.va.selfhelp.data.models.*
import com.coding.va.selfhelp.domain.constants.Constants.SETTINGS_KEY_SHEET_ID
import com.coding.va.selfhelp.domain.model.EntryType
import com.coding.va.selfhelp.domain.model.SheetEntryData
import com.coding.va.selfhelp.domain.respository.PrintingRepo
import com.russhwolf.settings.Settings
import io.ktor.client.*
import io.ktor.client.call.*
import io.ktor.client.request.*
import io.ktor.client.statement.bodyAsText
import io.ktor.http.ContentType
import io.ktor.http.contentType
import io.ktor.http.isSuccess
import kotlin.time.Clock
import kotlinx.serialization.Serializable
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json
import kotlin.io.encoding.Base64
import kotlin.io.encoding.ExperimentalEncodingApi
import kotlin.time.ExperimentalTime


import com.coding.va.selfhelp.BuildKonfig
import com.coding.va.selfhelp.data.di.SHEETS_CLIENT
import org.koin.core.annotation.Named
import org.koin.core.annotation.Single

@Single
@OptIn(ExperimentalTime::class)
class GoogleSheetsServiceImp(
    @Named(SHEETS_CLIENT) private val client: HttpClient,
    private val printingRepo: PrintingRepo,
) : GoogleSheetsService {

    private val json = Json { ignoreUnknownKeys = true }
    private val settings = Settings()

    private fun getSheetKey(): String {
        return settings.getString(SETTINGS_KEY_SHEET_ID, "")
    }

    @Serializable
    data class TokenResponse(
        val access_token: String,
        val expires_in: Int,
        val token_type: String
    )

    // Parse the service account JSON
    @Serializable
    data class ServiceAccount(
        val private_key: String = BuildKonfig.SHEETS_KEY,
        val client_email: String = BuildKonfig.SHEETS_EMAIL,
        val token_uri: String = "https://oauth2.googleapis.com/token"
    )

    @OptIn(ExperimentalEncodingApi::class)
    suspend fun getAccessToken(): String {
        val serviceAccount = ServiceAccount()

        // JWT Header
        val header = """{"alg":"RS256","typ":"JWT"}"""
        val headerEncoded = Base64.UrlSafe.encode(header.encodeToByteArray()).trimEnd('=')

        // JWT Payload
        val currentTime = Clock.System.now().epochSeconds
        val payload = """
            {
                "iss": "${serviceAccount.client_email}",
                "scope": "https://www.googleapis.com/auth/spreadsheets",
                "aud": "${serviceAccount.token_uri}",
                "exp": ${currentTime + 3600},
                "iat": $currentTime
            }
        """.trimIndent()
        val payloadEncoded = Base64.UrlSafe.encode(payload.encodeToByteArray()).trimEnd('=')

        // JWT Signature
        val unsignedToken = "$headerEncoded.$payloadEncoded"
        val signature = printingRepo.encryptRSA(unsignedToken, serviceAccount.private_key)
        val jwt = "$unsignedToken.$signature"

        // Request access token
        val response = client.post(serviceAccount.token_uri) {
            contentType(ContentType.Application.FormUrlEncoded)
            setBody("grant_type=urn:ietf:params:oauth:grant-type:jwt-bearer&assertion=$jwt")
        }

        val tokenResponse = json.decodeFromString<TokenResponse>(response.bodyAsText())
        return tokenResponse.access_token
    }

    override suspend fun createSheetEntry(type: EntryType): Result<SheetsAppendResponse> {
        val body = GoogleSheetsRequest(values = listOf(listOf(Clock.System.now().toString())))
        return Result.runCatching {
            client.post {
                url("/v4/spreadsheets/${getSheetKey()}/values/${type.sheet}!A1:append?valueInputOption=RAW")
                setBody(json.encodeToString(body))
                header("Authorization", "Bearer ${getAccessToken()}")
            }.let {
                if (it.status.isSuccess()) {
                    val responseText = it.body<SheetsAppendResponse>()
                    println("API Response: $responseText")
                    responseText
                } else {
                    println("API error: ${it.bodyAsText()}")
                    throw Exception(it.bodyAsText())
                }
            }
        }
    }

    override suspend fun updateSheetEntry(
        body: GoogleSheetsRequest,
        entry: SheetEntryData
    ): Result<SheetsAppendResponse> {
        return Result.runCatching {
            client.put {
                url("/v4/spreadsheets/${getSheetKey()}/values/${entry.type.sheet}!A${entry.rowNumber}:L${entry.rowNumber}?valueInputOption=RAW")
                setBody(json.encodeToString(body))
                header("Authorization", "Bearer ${getAccessToken()}")
            }.let {
                if (it.status.isSuccess()) {
                    val responseText = it.body<SheetsAppendResponse>()
                    println("API Response: $responseText")
                    responseText
                } else {
                    println("API error: ${it.bodyAsText()}")
                    throw Exception(it.bodyAsText())
                }
            }
        }
    }

    override suspend fun updatePrinted(
        body: GoogleSheetsRequest,
        entry: SheetEntryData
    ): Result<SheetsAppendResponse> {
        return Result.runCatching {
            client.put {
                url("/v4/spreadsheets/${getSheetKey()}/values/${entry.type.sheet}!E${entry.rowNumber}:E${entry.rowNumber}?valueInputOption=RAW")
                setBody(json.encodeToString(body))
                header("Authorization", "Bearer ${getAccessToken()}")
            }.let {
                if (it.status.isSuccess()) {
                    val responseText = it.body<SheetsAppendResponse>()
                    println("API Response: $responseText")
                    responseText
                } else {
                    println("API error: ${it.bodyAsText()}")
                    throw Exception(it.bodyAsText())
                }
            }
        }
    }

    override suspend fun getSheetEntry(
        entry: EntryData
    ): Result<GoogleSheetsEntryResponse> {
        return Result.runCatching {
            client.get {
                url("/v4/spreadsheets/${getSheetKey()}/values/${entry.type.sheet}!A${entry.rowNumber}:F${entry.rowNumber}")
                header("Authorization", "Bearer ${getAccessToken()}")
            }.let {
                if (it.status.isSuccess()) {
                    val responseText = it.body<GoogleSheetsEntryResponse>()
                    println("API Response: $responseText")
                    responseText
                } else {
                    println("API error: ${it.bodyAsText()}")
                    throw Exception(it.bodyAsText())
                }
            }
        }
    }
}