package com.coding.va.selfhelp.auth

import com.coding.va.selfhelp.di.sha256
import kotlin.io.encoding.Base64
import kotlin.io.encoding.ExperimentalEncodingApi
import kotlin.random.Random

/**
 * Generates a PKCE code_verifier / code_challenge pair (RFC 7636, method S256).
 *
 * @return Pair(codeVerifier, codeChallenge) — both base64url-encoded without padding.
 */
@OptIn(ExperimentalEncodingApi::class)
fun generatePkce(): Pair<String, String> {
    val verifierBytes = Random.nextBytes(32)
    val codeVerifier = Base64.UrlSafe.encode(verifierBytes).trimEnd('=')
    val codeChallenge = Base64.UrlSafe.encode(sha256(codeVerifier.encodeToByteArray())).trimEnd('=')
    return Pair(codeVerifier, codeChallenge)
}
